#!/usr/bin/env python3
"""Generates src/unicode_tables.rs with character class range tables."""
import unicodedata, sys

def ranges(pred):
    out = []
    start = None
    for cp in range(0x110000):
        ok = pred(cp)
        if ok and start is None:
            start = cp
        elif not ok and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out

def xid_continue(cp):
    if 0xD800 <= cp <= 0xDFFF:
        return False
    return ('a' + chr(cp)).isidentifier()

def punct(cp):
    return unicodedata.category(chr(cp)).startswith('P')

def printable_value(cp):
    cat = unicodedata.category(chr(cp))
    return cat not in ('Cc', 'Co', 'Cn', 'Zl', 'Zp', 'Cs')

def emit(name, rs):
    lines = ['pub static %s: &[(u32, u32)] = &[' % name]
    for a, b in rs:
        lines.append('    (0x%X, 0x%X),' % (a, b))
    lines.append('];')
    return '\n'.join(lines)

parts = ['// Generated by tools/gen_unicode.py (Unicode %s). Do not edit.' % unicodedata.unidata_version, '']
parts.append(emit('XID_CONTINUE', ranges(xid_continue)))
parts.append('')
parts.append(emit('PUNCTUATION', ranges(punct)))
parts.append('')
parts.append(emit('VALUE_CHAR', ranges(printable_value)))
parts.append('')
open(sys.argv[1], 'w').write('\n'.join(parts))
EOF
