//! Character class helpers backed by generated range tables.

use crate::unicode_tables::{PUNCTUATION, VALUE_CHAR, XID_CONTINUE};

fn in_table(table: &[(u32, u32)], c: char) -> bool {
    let cp = c as u32;
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

pub fn is_xid_continue(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    in_table(XID_CONTINUE, c)
}

pub fn is_punctuation(c: char) -> bool {
    in_table(PUNCTUATION, c)
}

pub fn is_value_char(c: char) -> bool {
    in_table(VALUE_CHAR, c)
}
