//! A small PEG parser for `mimeapps.list` files.
//!
//! The parser keeps track of failed rule attempts in the same way as the
//! `pest` parser generator does, so that parse errors can be reported with
//! the furthest position reached and the set of rules expected there.

use std::fmt;

use crate::unicode::{is_punctuation, is_value_char, is_xid_continue};

#[allow(non_camel_case_types)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Rule {
    EOI,
    file,
    section_char,
    name_char,
    value_char,
    section,
    comment,
    entry,
    name,
    value,
}

pub enum Line<'a> {
    Section(&'a str),
    Entry(&'a str, &'a str),
}

pub struct ParseError {
    positives: Vec<Rule>,
    negatives: Vec<Rule>,
    pos: usize,
    line_col: (usize, usize),
    line: String,
}

impl fmt::Debug for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Error {{ variant: ParsingError {{ positives: {:?}, negatives: {:?} }}, location: Pos({}), line_col: Pos(({}, {})), path: None, line: {:?}, continued_line: None }}",
            self.positives, self.negatives, self.pos, self.line_col.0, self.line_col.1, self.line
        )
    }
}

struct State<'a> {
    input: &'a str,
    pos: usize,
    attempt_pos: usize,
    pos_attempts: Vec<Rule>,
    neg_attempts: Vec<Rule>,
    lines: Vec<Line<'a>>,
}

impl<'a> State<'a> {
    fn attempts_at(&self, pos: usize) -> usize {
        if self.attempt_pos == pos {
            self.pos_attempts.len() + self.neg_attempts.len()
        } else {
            0
        }
    }

    fn track(&mut self, rule: Rule, pos: usize, pai: usize, nai: usize, prev: usize) {
        let curr = self.attempts_at(pos);
        if curr > prev && curr - prev == 1 {
            return;
        }
        if pos == self.attempt_pos {
            self.pos_attempts.truncate(pai);
            self.neg_attempts.truncate(nai);
        }
        if pos > self.attempt_pos {
            self.pos_attempts.clear();
            self.neg_attempts.clear();
            self.attempt_pos = pos;
        }
        if pos == self.attempt_pos {
            self.pos_attempts.push(rule);
        }
    }

    fn rule<F: FnOnce(&mut Self) -> bool>(&mut self, rule: Rule, f: F) -> bool {
        let actual_pos = self.pos;
        let (pai, nai) = if actual_pos == self.attempt_pos {
            (self.pos_attempts.len(), self.neg_attempts.len())
        } else {
            (0, 0)
        };
        let attempts = self.attempts_at(actual_pos);
        let ok = f(self);
        if !ok {
            self.pos = actual_pos;
            self.track(rule, actual_pos, pai, nai, attempts);
        }
        ok
    }

    fn lit(&mut self, s: &str) -> bool {
        if self.input[self.pos..].starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }

    fn char_if<P: Fn(char) -> bool>(&mut self, p: P) -> bool {
        match self.input[self.pos..].chars().next() {
            Some(c) if p(c) => {
                self.pos += c.len_utf8();
                true
            }
            _ => false,
        }
    }

    fn newline(&mut self) -> bool {
        self.lit("\n") || self.lit("\r\n") || self.lit("\r")
    }
}

fn section_char(s: &mut State) -> bool {
    s.rule(Rule::section_char, |s| {
        s.char_if(|c| is_xid_continue(c) || c == ' ' || c == '-')
    })
}

fn name_char(s: &mut State) -> bool {
    s.rule(Rule::name_char, |s| {
        s.char_if(|c| is_xid_continue(c) || is_punctuation(c) || c == ' ' || c == '+')
    })
}

fn value_char(s: &mut State) -> bool {
    s.rule(Rule::value_char, |s| s.char_if(is_value_char))
}

fn section(s: &mut State) -> bool {
    s.rule(Rule::section, |s| {
        let start = s.pos;
        if !s.lit("[") {
            return false;
        }
        let name_start = s.pos;
        if !section_char(s) {
            s.pos = start;
            return false;
        }
        while section_char(s) {}
        let name_end = s.pos;
        if !s.lit("]") {
            s.pos = start;
            return false;
        }
        let input = s.input;
        s.lines.push(Line::Section(&input[name_start..name_end]));
        true
    })
}

fn name(s: &mut State) -> bool {
    s.rule(Rule::name, |s| {
        if !name_char(s) {
            return false;
        }
        while name_char(s) {}
        true
    })
}

fn value(s: &mut State) -> bool {
    s.rule(Rule::value, |s| {
        if !value_char(s) {
            return false;
        }
        while value_char(s) {}
        true
    })
}

fn entry(s: &mut State) -> bool {
    s.rule(Rule::entry, |s| {
        let start = s.pos;
        if !name(s) {
            return false;
        }
        let key_end = s.pos;
        if !s.lit("=") {
            s.pos = start;
            return false;
        }
        let value_start = s.pos;
        if !value(s) {
            s.pos = start;
            return false;
        }
        let input = s.input;
        s.lines
            .push(Line::Entry(&input[start..key_end], &input[value_start..s.pos]));
        true
    })
}

fn comment(s: &mut State) -> bool {
    s.rule(Rule::comment, |s| {
        if !s.lit("#") {
            return false;
        }
        while name_char(s) {}
        true
    })
}

fn eoi(s: &mut State) -> bool {
    s.rule(Rule::EOI, |s| s.pos == s.input.len())
}

fn file(s: &mut State) -> bool {
    s.rule(Rule::file, |s| {
        loop {
            let save = s.pos;
            let save_lines = s.lines.len();
            let _ = section(s) || entry(s) || comment(s);
            if s.newline() {
                continue;
            }
            s.pos = save;
            s.lines.truncate(save_lines);
            break;
        }
        eoi(s)
    })
}

fn line_col(input: &str, pos: usize) -> (usize, usize) {
    let mut remaining = pos;
    let mut chars = input[..pos].chars().peekable();
    let mut lc = (1usize, 1usize);
    while remaining != 0 {
        match chars.next() {
            Some('\r') => {
                if let Some(&'\n') = chars.peek() {
                    chars.next();
                    if remaining == 1 {
                        remaining -= 1;
                    } else {
                        remaining -= 2;
                    }
                    lc = (lc.0 + 1, 1);
                } else {
                    remaining -= 1;
                    lc = (lc.0, lc.1 + 1);
                }
            }
            Some('\n') => {
                remaining -= 1;
                lc = (lc.0 + 1, 1);
            }
            Some(c) => {
                remaining -= c.len_utf8();
                lc = (lc.0, lc.1 + 1);
            }
            None => break,
        }
    }
    lc
}

fn line_of(input: &str, pos: usize) -> &str {
    if input.is_empty() {
        return "";
    }
    let start = input
        .char_indices()
        .rev()
        .skip_while(|&(i, _)| i >= pos)
        .find(|&(_, c)| c == '\n')
        .map(|(i, _)| i + 1)
        .unwrap_or(0);
    let end = if pos == input.len() - 1 {
        input.len()
    } else {
        input
            .char_indices()
            .skip_while(|&(i, _)| i < pos)
            .find(|&(_, c)| c == '\n')
            .map(|(i, _)| i + 1)
            .unwrap_or(input.len())
    };
    if start > end {
        return "";
    }
    &input[start..end]
}

fn visualize_whitespace(s: &str) -> String {
    s.replace('\r', "\u{240d}").replace('\n', "\u{240a}")
}

pub fn parse(input: &str) -> Result<Vec<Line<'_>>, ParseError> {
    let mut state = State {
        input,
        pos: 0,
        attempt_pos: 0,
        pos_attempts: Vec::new(),
        neg_attempts: Vec::new(),
        lines: Vec::new(),
    };
    if file(&mut state) {
        return Ok(state.lines);
    }
    let mut positives = state.pos_attempts.clone();
    positives.sort();
    positives.dedup();
    let mut negatives = state.neg_attempts.clone();
    negatives.sort();
    negatives.dedup();
    let pos = state.attempt_pos;
    Err(ParseError {
        positives,
        negatives,
        pos,
        line_col: line_col(input, pos),
        line: visualize_whitespace(line_of(input, pos)),
    })
}
EOF"}

