//! Media type parsing with the same normalisation and error reporting rules
//! as the commonly used `mime` crate.

use std::fmt;

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Mime {
    source: String,
    slash: usize,
    /// End of the essence (type/subtype) inside `source`.
    essence_end: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MimeError {
    MissingSlash,
    MissingEqual,
    MissingQuote,
    InvalidToken { pos: usize, byte: u8 },
}

impl fmt::Display for MimeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MimeError::MissingSlash => {
                f.write_str("a slash (/) was missing between the type and subtype")
            }
            MimeError::MissingEqual => {
                f.write_str("an equals sign (=) was missing between a parameter and its value")
            }
            MimeError::MissingQuote => {
                f.write_str("a quote (\") was missing from a parameter value")
            }
            MimeError::InvalidToken { pos, byte } => write!(
                f,
                "an invalid token was encountered, {:X} at position {}",
                byte, pos
            ),
        }
    }
}

fn is_token(c: u8) -> bool {
    c.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&c)
}

fn is_restricted_quoted_char(c: u8) -> bool {
    c > 31 && c != 127
}

impl Mime {
    pub fn parse(s: &str) -> Result<Mime, MimeError> {
        let bytes = s.as_bytes();
        let mut iter = bytes.iter().copied().enumerate();
        let slash;
        let mut start;
        loop {
            match iter.next() {
                Some((_, c)) if is_token(c) => {}
                Some((i, b'/')) if i > 0 => {
                    slash = i;
                    start = i + 1;
                    break;
                }
                None => return Err(MimeError::MissingSlash),
                Some((pos, byte)) => return Err(MimeError::InvalidToken { pos, byte }),
            }
        }
        loop {
            match iter.next() {
                Some((i, b'+')) if i > start => {}
                Some((i, b';')) if i > start => {
                    start = i;
                    break;
                }
                Some((_, c)) if is_token(c) => {}
                None => {
                    return Ok(Mime {
                        source: s.to_ascii_lowercase(),
                        slash,
                        essence_end: s.len(),
                    });
                }
                Some((pos, byte)) => return Err(MimeError::InvalidToken { pos, byte }),
            }
        }
        let semicolon = start;
        // Parameters
        let mut params: Vec<((usize, usize), (usize, usize))> = Vec::new();
        start += 1;
        'params: while start < s.len() {
            let name;
            loop {
                match iter.next() {
                    Some((i, b' ')) if i == start => {
                        start = i + 1;
                        continue 'params;
                    }
                    Some((_, c)) if is_token(c) => {}
                    Some((i, b'=')) if i > start => {
                        name = (start, i);
                        start = i + 1;
                        break;
                    }
                    None => return Err(MimeError::MissingEqual),
                    Some((pos, byte)) => return Err(MimeError::InvalidToken { pos, byte }),
                }
            }
            let value;
            let mut is_quoted = false;
            loop {
                if is_quoted {
                    match iter.next() {
                        Some((i, b'"')) if i > start => {
                            value = (start, i);
                            break;
                        }
                        Some((_, c)) if is_restricted_quoted_char(c) => {}
                        None => return Err(MimeError::MissingQuote),
                        Some((pos, byte)) => {
                            return Err(MimeError::InvalidToken { pos, byte })
                        }
                    }
                } else {
                    match iter.next() {
                        Some((i, b'"')) if i == start => {
                            is_quoted = true;
                            start = i + 1;
                        }
                        Some((_, c)) if is_token(c) => {}
                        Some((i, b';')) if i > start => {
                            value = (start, i);
                            start = i + 1;
                            break;
                        }
                        None => {
                            value = (start, s.len());
                            start = s.len();
                            break;
                        }
                        Some((pos, byte)) => {
                            return Err(MimeError::InvalidToken { pos, byte })
                        }
                    }
                }
            }
            if is_quoted {
                loop {
                    match iter.next() {
                        Some((i, b';')) => {
                            start = i + 1;
                            break;
                        }
                        Some((_, b' ')) => {}
                        None => {
                            start = s.len();
                            break;
                        }
                        Some((pos, byte)) => {
                            return Err(MimeError::InvalidToken { pos, byte })
                        }
                    }
                }
            }
            params.push((name, value));
        }
        if params.is_empty() {
            let src = s[..semicolon].to_ascii_lowercase();
            return Ok(Mime {
                essence_end: src.len(),
                source: src,
                slash,
            });
        }
        // Lowercase type/subtype, parameter names and charset values.
        let mut owned: Vec<u8> = bytes.to_vec();
        owned[..semicolon].make_ascii_lowercase();
        for (name, value) in &params {
            owned[name.0..name.1].make_ascii_lowercase();
            if &owned[name.0..name.1] == b"charset" {
                owned[value.0..value.1].make_ascii_lowercase();
            }
        }
        let source = String::from_utf8(owned).unwrap_or_else(|_| s.to_string());
        Ok(Mime {
            source,
            slash,
            essence_end: semicolon,
        })
    }

    pub fn type_(&self) -> &str {
        &self.source[..self.slash]
    }

    pub fn subtype(&self) -> &str {
        &self.source[self.slash + 1..self.essence_end]
    }

    pub fn essence(&self) -> &str {
        &self.source[..self.essence_end]
    }

    pub fn as_str(&self) -> &str {
        &self.source
    }

    /// Builds a mime from a string that is known to be valid.
    pub fn known(s: &str) -> Mime {
        Mime::parse(s).expect("valid mime")
    }
}

impl fmt::Display for Mime {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.source)
    }
}
