//! XDG base directory lookups.

use std::env;
use std::path::{Path, PathBuf};

pub fn home_dir() -> PathBuf {
    match env::var_os("HOME") {
        Some(h) if !h.is_empty() => PathBuf::from(h),
        _ => PathBuf::from("/"),
    }
}

fn abs_env(name: &str) -> Option<PathBuf> {
    let v = env::var_os(name)?;
    let p = PathBuf::from(v);
    if p.is_absolute() {
        Some(p)
    } else {
        None
    }
}

pub fn config_home() -> PathBuf {
    abs_env("XDG_CONFIG_HOME").unwrap_or_else(|| home_dir().join(".config"))
}

pub fn data_home() -> PathBuf {
    abs_env("XDG_DATA_HOME").unwrap_or_else(|| home_dir().join(".local/share"))
}

pub fn data_dirs() -> Vec<PathBuf> {
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Some(v) = env::var_os("XDG_DATA_DIRS") {
        for p in env::split_paths(&v) {
            if p.is_absolute() {
                dirs.push(p);
            }
        }
    }
    if dirs.is_empty() {
        dirs.push(PathBuf::from("/usr/local/share"));
        dirs.push(PathBuf::from("/usr/share"));
    }
    dirs
}

/// Data home followed by the system data directories.
pub fn all_data_dirs() -> Vec<PathBuf> {
    let mut v = vec![data_home()];
    v.extend(data_dirs());
    v
}

/// Finds the first existing `<data dir>/<rel>` path.
pub fn find_data_file(rel: &Path) -> Option<PathBuf> {
    for d in all_data_dirs() {
        let p = d.join(rel);
        if p.exists() {
            return Some(p);
        }
    }
    None
}

/// Lists the entries of `<data dir>/<sub>` for every data dir, keeping only
/// the first occurrence of every file name.
pub fn list_data_files_once(sub: &str) -> Vec<PathBuf> {
    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    for d in all_data_dirs() {
        if let Ok(rd) = std::fs::read_dir(d.join(sub)) {
            for e in rd.flatten() {
                let path = e.path();
                if let Some(name) = path.file_name() {
                    if seen.insert(name.to_owned()) {
                        out.push(path);
                    }
                }
            }
        }
    }
    out
}
EOF"}

