//! Parser for freedesktop `.desktop` files.

use std::collections::HashMap;

pub type Group = HashMap<String, String>;

struct Cursor<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Cursor<'a> {
    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn at_end(&self) -> bool {
        self.pos >= self.data.len()
    }

    /// Skips whitespace (space, tab, CR, LF) and `#` comments.
    fn skip_ws_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') => self.pos += 1,
                Some(b'#') => {
                    while let Some(c) = self.peek() {
                        if c == b'\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
    }
}

fn to_string(b: &[u8]) -> Option<String> {
    std::str::from_utf8(b).ok().map(|s| s.to_string())
}

fn parse_header(c: &mut Cursor) -> Option<Option<String>> {
    // Returns None on syntax error, Some(None) on invalid utf8.
