//! A reader for the freedesktop shared-mime-info database, used to guess the
//! media type of files from their name and contents.

use std::collections::HashMap;
use std::fs;
use std::io::Read;
use std::path::Path;

use crate::xdg;

#[derive(Clone, Debug)]
enum GlobKind {
    Literal(String),
    Suffix(String),
    Full(Vec<char>),
}

#[derive(Clone, Debug)]
struct Glob {
    weight: i32,
    mime: String,
    kind: GlobKind,
    case_sensitive: bool,
    len: usize,
}

#[derive(Clone, Debug)]
struct MagicRule {
    indent: usize,
    offset: usize,
    value: Vec<u8>,
    mask: Option<Vec<u8>>,
    word_size: usize,
    range: usize,
    children: Vec<MagicRule>,
}

#[derive(Clone, Debug)]
struct MagicEntry {
    priority: u32,
    mime: String,
    rules: Vec<MagicRule>,
}

pub struct MimeDb {
    globs: Vec<Glob>,
    magic: Vec<MagicEntry>,
    subclasses: HashMap<String, Vec<String>>,
    aliases: HashMap<String, String>,
    max_extent: usize,
}

fn glob_match(pattern: &[char], name: &[char]) -> bool {
    // Simple fnmatch implementation supporting '*', '?' and bracket classes.
    let (mut p, mut n) = (0usize, 0usize);
    let mut star: Option<(usize, usize)> = None;
    while n < name.len() {
        if p < pattern.len() {
            match pattern[p] {
                '*' => {
                    star = Some((p, n));
                    p += 1;
                    continue;
                }
                '?' => {
                    p += 1;
                    n += 1;
                    continue;
                }
                '[' => {
                    if let Some((matched, next)) = match_class(pattern, p, name[n]) {
                        if matched {
                            p = next;
                            n += 1;
                            continue;
                        }
                    } else if name[n] == '[' {
                        p += 1;
                        n += 1;
                        continue;
                    }
                }
                c => {
                    if c == name[n] {
                        p += 1;
                        n += 1;
                        continue;
                    }
                }
            }
        }
        if let Some((sp, sn)) = star {
            p = sp + 1;
            n = sn + 1;
            star = Some((sp, sn + 1));
            continue;
        }
        return false;
    }
    while p < pattern.len() && pattern[p] == '*' {
        p += 1;
    }
    p == pattern.len()
}

/// Returns (matched, index after class) or None if the class is unterminated.
fn match_class(pattern: &[char], start: usize, c: char) -> Option<(bool, usize)> {
    let mut i = start + 1;
    let mut negate = false;
    if i < pattern.len() && (pattern[i] == '!' || pattern[i] == '^') {
        negate = true;
        i += 1;
    }
    let mut matched = false;
    let mut first = true;
    while i < pattern.len() {
        if pattern[i] == ']' && !first {
            return Some((matched != negate, i + 1));
        }
        first = false;
        let lo = pattern[i];
        if i + 2 < pattern.len() && pattern[i + 1] == '-' && pattern[i + 2] != ']' {
            let hi = pattern[i + 2];
            if lo <= c && c <= hi {
                matched = true;
            }
            i += 3;
        } else {
            if lo == c {
                matched = true;
            }
            i += 1;
        }
    }
    None
}

impl Glob {
    fn new(weight: i32, mime: &str, pattern: &str, case_sensitive: bool) -> Glob {
        let special = |c: char| c == '*' || c == '?' || c == '[';
        let kind = if !pattern.chars().any(special) {
            GlobKind::Literal(pattern.to_string())
        } else if pattern.starts_with('*') && !pattern[1..].chars().any(special) {
            GlobKind::Suffix(pattern[1..].to_string())
        } else {
            GlobKind::Full(pattern.chars().collect())
        };
        Glob {
            weight,
            mime: mime.to_string(),
            kind,
            case_sensitive,
            len: pattern.chars().count(),
        }
    }

    fn matches(&self, name: &str) -> bool {
        match &self.kind {
            GlobKind::Literal(s) => {
                if self.case_sensitive {
                    s == name
                } else {
                    s.to_lowercase() == name.to_lowercase()
                }
            }
            GlobKind::Suffix(s) => {
                if self.case_sensitive {
                    name.ends_with(s.as_str())
                } else {
                    name.to_lowercase().ends_with(&s.to_lowercase())
                }
            }
            GlobKind::Full(p) => {
                if self.case_sensitive {
                    let n: Vec<char> = name.chars().collect();
                    glob_match(p, &n)
                } else {
                    let pl: Vec<char> = p.iter().collect::<String>().to_lowercase().chars().collect();
                    let n: Vec<char> = name.to_lowercase().chars().collect();
                    glob_match(&pl, &n)
                }
            }
        }
    }
}

fn parse_globs2(data: &str, out: &mut Vec<Glob>) {
    for line in data.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.splitn(4, ':');
        let weight = match parts.next().and_then(|w| w.parse::<i32>().ok()) {
            Some(w) => w,
            None => continue,
        };
        let mime = match parts.next() {
            Some(m) => m,
            None => continue,
        };
        let pattern = match parts.next() {
            Some(p) => p,
            None => continue,
        };
        let flags = parts.next().unwrap_or("");
        let cs = flags.split(',').any(|f| f == "cs");
        if pattern == "__NOGLOBS__" {
            out.retain(|g| g.mime != mime);
            continue;
        }
        out.push(Glob::new(weight, mime, pattern, cs));
    }
}

fn parse_globs1(data: &str, out: &mut Vec<Glob>) {
    for line in data.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some((mime, pattern)) = line.split_once(':') {
            out.push(Glob::new(50, mime, pattern, false));
        }
    }
}

fn parse_number(data: &[u8], pos: &mut usize) -> Option<usize> {
    let start = *pos;
    while *pos < data.len() && data[*pos].is_ascii_digit() {
        *pos += 1;
    }
    if *pos == start {
        return None;
    }
    std::str::from_utf8(&data[start..*pos]).ok()?.parse().ok()
}

fn parse_magic(data: &[u8], out: &mut Vec<MagicEntry>) -> Option<()> {
    let header = b"MIME-Magic\0\n";
    if !data.starts_with(header) {
        return None;
    }
    let mut pos = header.len();
    while pos < data.len() {
        if data[pos] != b'[' {
            return None;
        }
        pos += 1;
        let end = data[pos..].iter().position(|&c| c == b']')? + pos;
        let head = std::str::from_utf8(&data[pos..end]).ok()?;
        let (prio, mime) = head.split_once(':')?;
        let priority: u32 = prio.parse().ok()?;
        pos = end + 1;
        if data.get(pos) != Some(&b'\n') {
            return None;
        }
        pos += 1;
        let mut flat: Vec<MagicRule> = Vec::new();
        while pos < data.len() && data[pos] != b'[' {
            let indent = if data[pos] == b'>' {
                0
            } else {
                parse_number(data, &mut pos)?
            };
            if data.get(pos) != Some(&b'>') {
                return None;
            }
            pos += 1;
            let offset = parse_number(data, &mut pos)?;
            if data.get(pos) != Some(&b'=') {
                return None;
            }
            pos += 1;
            if pos + 2 > data.len() {
                return None;
            }
            let vlen = ((data[pos] as usize) << 8) | data[pos + 1] as usize;
            pos += 2;
            if pos + vlen > data.len() {
                return None;
            }
            let value = data[pos..pos + vlen].to_vec();
            pos += vlen;
            let mut mask = None;
            if data.get(pos) == Some(&b'&') {
                pos += 1;
                if pos + vlen > data.len() {
                    return None;
                }
                mask = Some(data[pos..pos + vlen].to_vec());
                pos += vlen;
            }
            let mut word_size = 1;
            if data.get(pos) == Some(&b'~') {
                pos += 1;
                word_size = parse_number(data, &mut pos)?;
            }
            let mut range = 1;
            if data.get(pos) == Some(&b'+') {
                pos += 1;
                range = parse_number(data, &mut pos)?;
            }
            // Skip unknown trailing data up to the end of the line.
            while pos < data.len() && data[pos] != b'\n' {
                pos += 1;
            }
            if pos < data.len() {
                pos += 1;
            }
            flat.push(MagicRule {
                indent,
                offset,
                value,
                mask,
                word_size,
                range,
                children: Vec::new(),
            });
        }
        out.push(MagicEntry {
            priority,
            mime: mime.to_string(),
            rules: build_tree(flat),
        });
    }
    Some(())
}

fn build_tree(flat: Vec<MagicRule>) -> Vec<MagicRule> {
    fn insert(level: &mut Vec<MagicRule>, rule: MagicRule, depth: usize) {
        if rule.indent > depth {
            if let Some(last) = level.last_mut() {
                insert(&mut last.children, rule, depth + 1);
                return;
            }
        }
        level.push(rule);
    }
    let mut top = Vec::new();
    for r in flat {
        insert(&mut top, r, 0);
    }
    top
}

fn rule_extent(r: &MagicRule) -> usize {
    let own = r.offset + r.value.len() + r.range;
    r.children.iter().map(rule_extent).fold(own, usize::max)
}

impl MagicRule {
    fn matches_here(&self, data: &[u8]) -> bool {
        let mut value = self.value.clone();
        let mut mask = self.mask.clone();
        if self.word_size > 1 && cfg!(target_endian = "little") {
            let ws = self.word_size;
            for chunk in value.chunks_mut(ws) {
                chunk.reverse();
            }
            if let Some(m) = mask.as_mut() {
                for chunk in m.chunks_mut(ws) {
                    chunk.reverse();
                }
            }
        }
        for start in self.offset..self.offset + self.range.max(1) {
            if start + value.len() > data.len() {
                break;
            }
            let ok = match &mask {
                Some(m) => (0..value.len()).all(|i| data[start + i] & m[i] == value[i] & m[i]),
                None => &data[start..start + value.len()] == value.as_slice(),
            };
            if ok {
                return true;
            }
        }
        false
    }

    fn matches(&self, data: &[u8]) -> bool {
        if !self.matches_here(data) {
            return false;
        }
        self.children.is_empty() || self.children.iter().any(|c| c.matches(data))
    }
}

pub fn looks_like_text(data: &[u8]) -> bool {
    !data
        .iter()
        .any(|&b| b.is_ascii_control() && !b.is_ascii_whitespace())
}

impl MimeDb {
    pub fn load() -> MimeDb {
        let mut globs = Vec::new();
        let mut magic = Vec::new();
        let mut subclasses: HashMap<String, Vec<String>> = HashMap::new();
        let mut aliases = HashMap::new();
        for dir in xdg::all_data_dirs() {
            let mdir = dir.join("mime");
            if let Ok(s) = fs::read_to_string(mdir.join("globs2")) {
                parse_globs2(&s, &mut globs);
            } else if let Ok(s) = fs::read_to_string(mdir.join("globs")) {
                parse_globs1(&s, &mut globs);
            }
            if let Ok(d) = fs::read(mdir.join("magic")) {
                let mut entries = Vec::new();
                if parse_magic(&d, &mut entries).is_some() {
                    magic.extend(entries);
                }
            }
            if let Ok(s) = fs::read_to_string(mdir.join("subclasses")) {
                for line in s.lines() {
                    let mut it = line.split_whitespace();
                    if let (Some(a), Some(b)) = (it.next(), it.next()) {
                        subclasses.entry(a.to_string()).or_default().push(b.to_string());
                    }
                }
            }
            if let Ok(s) = fs::read_to_string(mdir.join("aliases")) {
                for line in s.lines() {
                    let mut it = line.split_whitespace();
                    if let (Some(a), Some(b)) = (it.next(), it.next()) {
                        aliases.entry(a.to_string()).or_insert_with(|| b.to_string());
                    }
                }
            }
        }
        magic.sort_by(|a, b| b.priority.cmp(&a.priority));
        let max_extent = magic
            .iter()
            .flat_map(|e| e.rules.iter())
            .map(rule_extent)
            .max()
            .unwrap_or(0);
        MimeDb {
            globs,
            magic,
            subclasses,
            aliases,
            max_extent,
        }
    }

    fn unalias<'a>(&'a self, m: &'a str) -> &'a str {
        self.aliases.get(m).map(|s| s.as_str()).unwrap_or(m)
    }

    /// Returns the list of mime types matching the file name.
    pub fn mime_types_from_file_name(&self, name: &str) -> Vec<String> {
        let mut matching: Vec<&Glob> = self.globs.iter().filter(|g| g.matches(name)).collect();
        matching.sort_by(|a, b| a.weight.cmp(&b.weight).then(b.len.cmp(&a.len)));
        let mut out: Vec<String> = Vec::new();
        for g in matching {
            if !out.contains(&g.mime) {
                out.push(g.mime.clone());
            }
        }
        out
    }

    fn magic_lookup(&self, data: &[u8]) -> Option<String> {
        for entry in &self.magic {
            if entry.rules.iter().any(|r| r.matches(data)) {
                return Some(entry.mime.clone());
            }
        }
        None
    }

    pub fn is_subclass(&self, a: &str, b: &str) -> bool {
        self.is_subclass_depth(a, b, 0)
    }

    fn is_subclass_depth(&self, a: &str, b: &str, depth: usize) -> bool {
        let a = self.unalias(a);
        let b = self.unalias(b);
        if a == b {
            return true;
        }
        if depth > 16 {
            return false;
        }
        if b == "text/plain" && a.starts_with("text/") {
            return true;
        }
        if b == "application/octet-stream" && !a.starts_with("inode/") {
            return true;
        }
        if let Some(parents) = self.subclasses.get(a) {
            for p in parents {
                if self.is_subclass_depth(p, b, depth + 1) {
                    return true;
                }
            }
        }
        false
    }

    /// Guesses the mime type of the file at `path`.
    pub fn guess(&self, path: &Path) -> String {
        if let Ok(meta) = fs::metadata(path) {
            if meta.is_dir() {
                return "inode/directory".into();
            }
            if meta.len() == 0 {
                return "application/x-zerosize".into();
            }
        }
        let names = match path.file_name().and_then(|n| n.to_str()) {
            Some(n) => self.mime_types_from_file_name(n),
            None => Vec::new(),
        };
        if names.len() == 1 {
            return names[0].clone();
        }
        let mut data = Vec::new();
        if self.max_extent > 0 {
            if let Ok(f) = fs::File::open(path) {
                let _ = f.take(self.max_extent as u64).read_to_end(&mut data);
            }
        }
        if data.is_empty() {
            return "application/x-zerosize".into();
        }
        match self.magic_lookup(&data) {
            Some(sniffed) => {
                if names.is_empty() || names.iter().any(|n| self.is_subclass(&sniffed, n)) {
                    sniffed
                } else {
                    names[0].clone()
                }
            }
            None => {
                if looks_like_text(&data) {
                    "text/plain".into()
                } else if names.is_empty() {
                    "application/octet-stream".into()
                } else {
                    names[0].clone()
                }
            }
        }
    }
}
