//! A WHATWG-style URL parser covering the subset needed to recognise and
//! normalise URLs passed on the command line.

pub struct Url {
    pub scheme: String,
    username: String,
    password: String,
    host: Option<String>,
    port: Option<u16>,
    path: String,
    query: Option<String>,
    fragment: Option<String>,
    has_authority: bool,
}

const SPECIAL: &[(&str, Option<u16>)] = &[
    ("ftp", Some(21)),
    ("file", None),
    ("http", Some(80)),
    ("https", Some(443)),
    ("ws", Some(80)),
    ("wss", Some(443)),
];

fn is_special(s: &str) -> bool {
    SPECIAL.iter().any(|(n, _)| *n == s)
}

fn default_port(s: &str) -> Option<u16> {
    SPECIAL.iter().find(|(n, _)| *n == s).and_then(|(_, p)| *p)
}

#[derive(Clone, Copy)]
enum Set {
    C0,
    Fragment,
    Query,
    SpecialQuery,
    Path,
    Userinfo,
}

fn in_set(set: Set, c: char) -> bool {
    let cp = c as u32;
    let c0 = cp < 0x20 || cp > 0x7E;
    match set {
        Set::C0 => c0,
        Set::Fragment => c0 || " \"<>`".contains(c),
        Set::Query => c0 || " \"#<>".contains(c),
        Set::SpecialQuery => c0 || " \"#<>'".contains(c),
        Set::Path => c0 || " \"#<>?`{}".contains(c),
        Set::Userinfo => c0 || " \"#<>?`{}/:;=@[\\]^|".contains(c),
    }
}

fn encode_char(out: &mut String, c: char, set: Set) {
    if in_set(set, c) {
        let mut buf = [0u8; 4];
        for b in c.encode_utf8(&mut buf).bytes() {
            out.push_str(&format!("%{:02X}", b));
        }
    } else {
        out.push(c);
    }
}

fn encode_str(s: &str, set: Set) -> String {
    let mut out = String::new();
    for c in s.chars() {
        encode_char(&mut out, c, set);
    }
    out
}

pub fn percent_decode(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 0 {
            let h = (b[i + 1] as char).to_digit(16);
            let l = (b[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    out
}

fn is_single_dot(s: &str) -> bool {
    s == "." || s.eq_ignore_ascii_case("%2e")
}

fn is_double_dot(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    l == ".." || l == ".%2e" || l == "%2e." || l == "%2e%2e"
}

fn parse_path(input: &str, special: bool, segments: &mut Vec<String>) {
    // `input` is the path part, without query/fragment.
    let is_sep = |c: char| c == '/' || (special && c == '\\');
    let mut buffer = String::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    loop {
        let c = chars.get(i).copied();
        if c.is_none() || is_sep(c.unwrap()) {
            let at_end = c.is_none();
            if is_double_dot(&buffer) {
                segments.pop();
                if at_end {
                    segments.push(String::new());
                }
            } else if is_single_dot(&buffer) {
                if at_end {
                    segments.push(String::new());
                }
            } else {
                segments.push(std::mem::take(&mut buffer));
            }
            buffer.clear();
            if at_end {
                break;
            }
        } else {
            encode_char(&mut buffer, c.unwrap(), Set::Path);
        }
        i += 1;
    }
}

// ---- Host parsing ----

fn forbidden_host(c: char) -> bool {
    matches!(
        c,
        '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '|'
    )
}

fn forbidden_domain(c: char) -> bool {
    forbidden_host(c) || (c as u32) <= 0x1F || c == '%' || c == '\u{7f}'
}

fn punycode_encode(input: &str) -> Option<String> {
    let base: u32 = 36;
    let tmin = 1;
    let tmax = 26;
    let skew = 38;
    let damp = 700;
    let mut n: u32 = 128;
    let mut delta: u32 = 0;
    let mut bias: u32 = 72;
    let cps: Vec<u32> = input.chars().map(|c| c as u32).collect();
    let mut output: String = cps.iter().filter(|&&c| c < 128).map(|&c| c as u8 as char).collect();
    let b = output.len() as u32;
    let mut h = b;
    if b > 0 {
        output.push('-');
    }
    fn digit(d: u32) -> char {
        if d < 26 {
            (b'a' + d as u8) as char
        } else {
            (b'0' + (d - 26) as u8) as char
        }
    }
    fn adapt(mut delta: u32, numpoints: u32, first: bool) -> u32 {
        delta = if first { delta / 700 } else { delta / 2 };
        delta += delta / numpoints;
        let mut k = 0;
        while delta > ((36 - 1) * 26) / 2 {
            delta /= 36 - 1;
            k += 36;
        }
        k + (36 * delta) / (delta + 38)
    }
    let _ = (skew, damp);
    while (h as usize) < cps.len() {
        let m = *cps.iter().filter(|&&c| c >= n).min()?;
        delta = delta.checked_add((m - n).checked_mul(h + 1)?)?;
        n = m;
        for &c in &cps {
            if c < n {
                delta = delta.checked_add(1)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = base;
                loop {
                    let t = if k <= bias {
                        tmin
                    } else if k >= bias + tmax {
                        tmax
                    } else {
                        k - bias
                    };
                    if q < t {
                        break;
                    }
                    output.push(digit(t + (q - t) % (base - t)));
                    q = (q - t) / (base - t);
                    k += base;
                }
                output.push(digit(q));
                bias = adapt(delta, h + 1, h == b);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    Some(output)
}

fn domain_to_ascii(domain: &str) -> Option<String> {
    let lowered = domain.to_lowercase();
    let mut labels = Vec::new();
    for label in lowered.split(|c| c == '.' || c == '\u{3002}' || c == '\u{ff0e}' || c == '\u{ff61}') {
        if label.is_ascii() {
            labels.push(label.to_string());
        } else {
            labels.push(format!("xn--{}", punycode_encode(label)?));
        }
    }
    Some(labels.join("."))
}

fn parse_ipv4_number(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let (digits, radix) = if s.len() >= 2 && (s.starts_with("0x") || s.starts_with("0X")) {
        (&s[2..], 16)
    } else if s.len() >= 2 && s.starts_with('0') {
        (&s[1..], 8)
    } else {
        (s, 10)
    };
    if digits.is_empty() {
        return Some(0);
    }
    u64::from_str_radix(digits, radix).ok().or_else(|| {
        if digits.chars().all(|c| c.is_digit(radix)) {
            Some(u64::MAX)
        } else {
            None
        }
    })
}

fn ends_in_number(s: &str) -> bool {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") {
        if parts.len() == 1 {
            return false;
        }
        parts.pop();
    }
    let last = parts.last().copied().unwrap_or("");
    if !last.is_empty() && last.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }
    if (last.starts_with("0x") || last.starts_with("0X"))
        && last[2..].chars().all(|c| c.is_ascii_hexdigit())
    {
        return true;
    }
    false
}

fn parse_ipv4(s: &str) -> Option<String> {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") && parts.len() > 1 {
        parts.pop();
    }
    if parts.len() > 4 {
        return None;
    }
    let mut nums = Vec::new();
    for p in &parts {
        nums.push(parse_ipv4_number(p)?);
    }
    for n in &nums[..nums.len() - 1] {
        if *n > 255 {
            return None;
        }
    }
    let last = *nums.last()?;
    if last >= 256u64.pow(5 - nums.len() as u32) {
        return None;
    }
    let mut ipv4 = last;
    for (i, n) in nums[..nums.len() - 1].iter().enumerate() {
        ipv4 += n * 256u64.pow(3 - i as u32);
    }
    Some(format!(
        "{}.{}.{}.{}",
        (ipv4 >> 24) & 255,
        (ipv4 >> 16) & 255,
        (ipv4 >> 8) & 255,
        ipv4 & 255
    ))
}

fn parse_ipv6(input: &str) -> Option<String> {
    let c: Vec<char> = input.chars().collect();
    let mut addr = [0u16; 8];
    let mut piece = 0usize;
    let mut compress: Option<usize> = None;
    let mut p = 0usize;
    if c.get(0) == Some(&':') {
        if c.get(1) != Some(&':') {
            return None;
        }
        p += 2;
        piece += 1;
        compress = Some(piece);
    }
    while p < c.len() {
        if piece == 8 {
            return None;
        }
        if c[p] == ':' {
            if compress.is_some() {
                return None;
            }
            p += 1;
            piece += 1;
            compress = Some(piece);
            continue;
        }
        let mut value: u32 = 0;
        let mut length = 0;
        while length < 4 && p < c.len() && c[p].is_ascii_hexdigit() {
            value = value * 16 + c[p].to_digit(16).unwrap();
            p += 1;
            length += 1;
        }
        if p < c.len() && c[p] == '.' {
            if length == 0 {
                return None;
            }
            p -= length;
            if piece > 6 {
                return None;
            }
            let mut numbers_seen = 0;
            while p < c.len() {
                let mut ipv4_piece: Option<u32> = None;
                if numbers_seen > 0 {
                    if c[p] == '.' && numbers_seen < 4 {
                        p += 1;
                    } else {
                        return None;
                    }
                }
                if p >= c.len() || !c[p].is_ascii_digit() {
                    return None;
                }
                while p < c.len() && c[p].is_ascii_digit() {
                    let n = c[p].to_digit(10).unwrap();
                    ipv4_piece = match ipv4_piece {
                        None => Some(n),
                        Some(0) => return None,
                        Some(v) => Some(v * 10 + n),
                    };
                    if ipv4_piece.unwrap() > 255 {
                        return None;
                    }
                    p += 1;
                }
                addr[piece] = (addr[piece] as u32 * 0x100 + ipv4_piece.unwrap()) as u16;
                numbers_seen += 1;
                if numbers_seen == 2 || numbers_seen == 4 {
                    piece += 1;
                }
            }
            if numbers_seen != 4 {
                return None;
            }
            break;
        } else if p < c.len() && c[p] == ':' {
            p += 1;
            if p >= c.len() {
                return None;
            }
        } else if p < c.len() {
            return None;
        }
        addr[piece] = value as u16;
        piece += 1;
    }
    if let Some(comp) = compress {
        let mut swaps = piece - comp;
        piece = 7;
        while piece != 0 && swaps > 0 {
            addr.swap(piece, comp + swaps - 1);
            piece -= 1;
            swaps -= 1;
        }
    } else if piece != 8 {
        return None;
    }
    // Serialize
    let mut best: Option<(usize, usize)> = None;
    let mut i = 0;
    while i < 8 {
        if addr[i] == 0 {
            let start = i;
            while i < 8 && addr[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len > 1 && best.map_or(true, |(_, l)| len > l) {
                best = Some((start, len));
            }
        } else {
            i += 1;
        }
    }
    let mut out = String::from("[");
    let mut ignore0 = false;
    let mut i = 0;
    while i < 8 {
        if ignore0 && addr[i] == 0 {
            i += 1;
            continue;
        }
        ignore0 = false;
        if let Some((s, _)) = best {
            if s == i {
                out.push_str(if i == 0 { "::" } else { ":" });
                ignore0 = true;
                i += 1;
                continue;
            }
        }
        out.push_str(&format!("{:x}", addr[i]));
        if i != 7 {
            out.push(':');
        }
        i += 1;
    }
    out.push(']');
    Some(out)
}

fn parse_host(input: &str, special: bool) -> Option<String> {
    if input.starts_with('[') {
        if !input.ends_with(']') {
            return None;
        }
        return parse_ipv6(&input[1..input.len() - 1]);
    }
    if !special {
        if input.chars().any(|c| forbidden_host(c) && c != '%') {
            return None;
        }
        return Some(encode_str(input, Set::C0));
    }
    let decoded = String::from_utf8_lossy(&percent_decode(input)).into_owned();
    let ascii = domain_to_ascii(&decoded)?;
    if ascii.is_empty() {
        return None;
    }
    if ascii.chars().any(forbidden_domain) {
        return None;
    }
    if ends_in_number(&ascii) {
        return parse_ipv4(&ascii);
    }
    Some(ascii)
}

impl Url {
    pub fn parse(input: &str) -> Option<Url> {
        let trimmed = input.trim_matches(|c: char| (c as u32) <= 0x20);
        let s: String = trimmed.chars().filter(|&c| c != '\t' && c != '\n' && c != '\r').collect();
        // Scheme
        let mut chars = s.char_indices();
        match chars.next() {
            Some((_, c)) if c.is_ascii_alphabetic() => {}
            _ => return None,
        }
        let mut colon = None;
        for (i, c) in chars {
            if c == ':' {
                colon = Some(i);
                break;
            }
            if !(c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
                return None;
            }
        }
        let colon = colon?;
        let scheme = s[..colon].to_ascii_lowercase();
        let rest = &s[colon + 1..];
        let special = is_special(&scheme);

        let mut url = Url {
            scheme: scheme.clone(),
            username: String::new(),
            password: String::new(),
            host: None,
            port: None,
            path: String::new(),
            query: None,
            fragment: None,
            has_authority: false,
        };

        // Split off fragment and query.
        let (before_frag, fragment) = match rest.find('#') {
            Some(i) => (&rest[..i], Some(&rest[i + 1..])),
            None => (rest, None),
        };
        let (before_query, query) = match before_frag.find('?') {
            Some(i) => (&before_frag[..i], Some(&before_frag[i + 1..])),
            None => (before_frag, None),
        };
        url.fragment = fragment.map(|f| encode_str(f, Set::Fragment));
        url.query = query.map(|q| encode_str(q, if special { Set::SpecialQuery } else { Set::Query }));

        let is_slash = |c: char| c == '/' || (special && c == '\\');

        if scheme == "file" {
            url.has_authority = true;
            let b: Vec<char> = before_query.chars().collect();
            let mut path_part: String;
            if b.len() >= 2 && is_slash(b[0]) && is_slash(b[1]) {
                let after: String = b[2..].iter().collect();
                let end = after.find(|c: char| is_slash(c)).unwrap_or(after.len());
                let host_str = &after[..end];
                path_part = after[end..].to_string();
                if !host_str.is_empty() {
                    let h = parse_host(host_str, true)?;
                    if h != "localhost" {
                        url.host = Some(h);
                    }
                }
            } else {
                path_part = before_query.to_string();
            }
            if path_part.starts_with(|c: char| is_slash(c)) {
                path_part = path_part[1..].to_string();
            }
            let mut segs = Vec::new();
            parse_path(&path_part, true, &mut segs);
            url.path = format!("/{}", segs.join("/"));
            if url.host.is_none() {
                url.host = Some(String::new());
            }
            return Some(url);
        }

        if special {
            // Skip any slashes before the authority.
            let auth_start = before_query
                .find(|c: char| !is_slash(c))
                .unwrap_or(before_query.len());
            let after = &before_query[auth_start..];
            let auth_end = after.find(|c: char| is_slash(c)).unwrap_or(after.len());
            let authority = &after[..auth_end];
            let path_part = &after[auth_end..];
            url.has_authority = true;
            Self::parse_authority(&mut url, authority, true)?;
            let p = if path_part.starts_with(|c: char| is_slash(c)) {
                &path_part[1..]
            } else {
                path_part
            };
            let mut segs = Vec::new();
            parse_path(p, true, &mut segs);
            url.path = format!("/{}", segs.join("/"));
            return Some(url);
        }

        // Non-special schemes.
        if let Some(after) = before_query.strip_prefix("//") {
            let auth_end = after.find('/').unwrap_or(after.len());
            let authority = &after[..auth_end];
            let path_part = &after[auth_end..];
            url.has_authority = true;
            Self::parse_authority(&mut url, authority, false)?;
            if !path_part.is_empty() {
                let mut segs = Vec::new();
                parse_path(&path_part[1..], false, &mut segs);
                url.path = format!("/{}", segs.join("/"));
            }
            return Some(url);
        }
        if let Some(p) = before_query.strip_prefix('/') {
            let mut segs = Vec::new();
            parse_path(p, false, &mut segs);
            url.path = format!("/{}", segs.join("/"));
            return Some(url);
        }
        // Opaque path.
        url.path = encode_str(before_query, Set::C0);
        Some(url)
    }

    fn parse_authority(url: &mut Url, authority: &str, special: bool) -> Option<()> {
        let (userinfo, hostport) = match authority.rfind('@') {
            Some(i) => (Some(&authority[..i]), &authority[i + 1..]),
            None => (None, authority),
        };
        if let Some(ui) = userinfo {
            let (u, p) = match ui.find(':') {
                Some(i) => (&ui[..i], Some(&ui[i + 1..])),
                None => (ui, None),
            };
            url.username = encode_str(u, Set::Userinfo);
            url.password = p.map(|p| encode_str(p, Set::Userinfo)).unwrap_or_default();
        }
        // Split host and port (respecting IPv6 brackets).
        let mut in_brackets = false;
        let mut port_at = None;
        for (i, c) in hostport.char_indices() {
            match c {
                '[' => in_brackets = true,
                ']' => in_brackets = false,
                ':' if !in_brackets => {
                    port_at = Some(i);
                    break;
                }
                _ => {}
            }
        }
        let (host_str, port_str) = match port_at {
            Some(i) => (&hostport[..i], Some(&hostport[i + 1..])),
            None => (hostport, None),
        };
        if host_str.is_empty() {
            if special || userinfo.is_some() || port_str.is_some() {
                return None;
            }
            url.host = Some(String::new());
        } else {
            url.host = Some(parse_host(host_str, special)?);
        }
        if let Some(ps) = port_str {
            if !ps.is_empty() {
                if !ps.chars().all(|c| c.is_ascii_digit()) {
                    return None;
                }
                let n: u32 = ps.trim_start_matches('0').parse().unwrap_or(0);
                let n = if ps.trim_start_matches('0').len() > 5 { 70000 } else { n };
                if n > 65535 {
                    return None;
                }
                if Some(n as u16) != default_port(&url.scheme) {
                    url.port = Some(n as u16);
                }
            }
        }
        Some(())
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn host_is_empty(&self) -> bool {
        self.host.as_deref().map_or(true, |h| h.is_empty())
    }

    pub fn serialize(&self) -> String {
        let mut out = format!("{}:", self.scheme);
        if self.has_authority {
            out.push_str("//");
            if !self.username.is_empty() || !self.password.is_empty() {
                out.push_str(&self.username);
                if !self.password.is_empty() {
                    out.push(':');
                    out.push_str(&self.password);
                }
                out.push('@');
            }
            if let Some(h) = &self.host {
                out.push_str(h);
            }
            if let Some(p) = self.port {
                out.push_str(&format!(":{}", p));
            }
        } else if self.path.starts_with("//") {
            out.push_str("/.");
        }
        out.push_str(&self.path);
        if let Some(q) = &self.query {
            out.push('?');
            out.push_str(q);
        }
        if let Some(f) = &self.fragment {
            out.push('#');
            out.push_str(f);
        }
        out
    }

    /// Converts a `file:` URL into a local path.
    pub fn to_file_path(&self) -> Option<std::path::PathBuf> {
        use std::os::unix::ffi::OsStringExt;
        if !self.host_is_empty() {
            return None;
        }
        let bytes = percent_decode(&self.path);
        Some(std::path::PathBuf::from(std::ffi::OsString::from_vec(bytes)))
    }
}
EOF"}

