            if min_bound <= j && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let d = jaro(a, b);
    let prefix = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    let jw = d + (0.1 * prefix as f64 * (1.0 - d));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

/// Returns the best candidate with a similarity above 0.8.
pub fn did_you_mean<'a>(v: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut scored: Vec<(f64, &'a str)> = candidates
        .iter()
        .map(|c| (jaro_winkler(v, c), *c))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    scored.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    scored.pop().map(|(_, c)| c)
}
