//! Box-drawing table rendering limited to a total width of 80 columns.

const MAX_WIDTH: usize = 80;

fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn truncate(s: &str, width: usize) -> String {
    if char_len(s) <= width {
        return s.to_string();
    }
    if width == 0 {
        return String::new();
    }
    let mut out: String = s.chars().take(width - 1).collect();
    out.push('+');
    out
}

pub fn render(rows: &[(String, String)]) -> String {
    if rows.is_empty() {
        return "┌──┐\n│  │\n└──┘".to_string();
    }
    let mut widths = [0usize; 2];
    for (a, b) in rows {
        widths[0] = widths[0].max(char_len(a));
        widths[1] = widths[1].max(char_len(b));
    }
    // Borders and padding: "│ " + " │ " + " │"
    let overhead = 7;
    while widths[0] + widths[1] + overhead > MAX_WIDTH {
        // Decrease the widest column; on ties the last one.
        let col = if widths[1] >= widths[0] { 1 } else { 0 };
        if widths[col] == 0 {
            break;
        }
        widths[col] -= 1;
    }
    let mut out = String::new();
    out.push('┌');
    out.push_str(&"─".repeat(widths[0] + 2));
    out.push('┬');
    out.push_str(&"─".repeat(widths[1] + 2));
    out.push_str("┐\n");
    for (a, b) in rows {
        let a = truncate(a, widths[0]);
        let b = truncate(b, widths[1]);
        out.push_str("│ ");
        out.push_str(&a);
        out.push_str(&" ".repeat(widths[0] - char_len(&a)));
        out.push_str(" │ ");
        out.push_str(&b);
        out.push_str(&" ".repeat(widths[1] - char_len(&b)));
        out.push_str(" │\n");
    }
    out.push('└');
    out.push_str(&"─".repeat(widths[0] + 2));
    out.push('┴');
    out.push_str(&"─".repeat(widths[1] + 2));
    out.push('┘');
    out
}
