//! A small TOML parser producing errors in the same shape as the `toml`
//! crate (0.5 series), sufficient for reading the handlr configuration file.

use std::fmt;

#[derive(Debug, Clone)]
pub enum Kind {
    UnexpectedEof,
    InvalidCharInString(char),
    InvalidEscape(char),
    InvalidHexEscape(char),
    InvalidEscapeValue(u32),
    NewlineInString,
    Unexpected(char),
    UnterminatedString,
    NewlineInTableKey,
    NumberInvalid,
    DateInvalid,
    Wanted { expected: &'static str, found: &'static str },
    DuplicateTable(String),
    RedefineAsArray,
    EmptyTableKey,
    MultilineStringKey,
    Custom,
    UnquotedString,
}

pub struct TomlError {
    pub kind: Kind,
    pub line: Option<usize>,
    pub col: usize,
    pub at: Option<usize>,
    pub message: String,
    pub key: Vec<String>,
}

impl fmt::Debug for TomlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Error {{ inner: ErrorInner {{ kind: {:?}, line: {:?}, col: {}, at: {:?}, message: {:?}, key: {:?} }} }}",
            self.kind, self.line, self.col, self.at, self.message, self.key
        )
    }
}

#[derive(Debug, Clone)]
pub enum Value {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

#[derive(Debug, Clone)]
pub struct Spanned {
    pub value: Value,
    /// Byte offset of the value, when known.
    pub start: Option<usize>,
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Whitespace,
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    Plus,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(String),
    Str { val: String, multiline: bool, literal: bool },
}

impl Tok {
    fn describe(&self) -> &'static str {
        match self {
            Tok::Keylike(_) => "an identifier",
            Tok::Equals => "an equals",
            Tok::Period => "a period",
            Tok::Comment => "a comment",
            Tok::Newline => "a newline",
            Tok::Whitespace => "whitespace",
            Tok::Comma => "a comma",
            Tok::RightBrace => "a right brace",
            Tok::LeftBrace => "a left brace",
            Tok::RightBracket => "a right bracket",
            Tok::LeftBracket => "a left bracket",
            Tok::Str { multiline, .. } => {
                if *multiline {
                    "a multiline string"
                } else {
                    "a string"
                }
            }
            Tok::Colon => "a colon",
            Tok::Plus => "a plus",
        }
    }
}

struct Lexer<'a> {
    input: &'a str,
    pos: usize,
}

type LResult<T> = Result<T, (usize, Kind)>;

fn is_keylike(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '-' || c == '_'
}

impl<'a> Lexer<'a> {
    fn peek_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn peek_char_at(&self, off: usize) -> Option<char> {
        self.input[self.pos..].chars().nth(off)
    }

    fn next(&mut self) -> LResult<Option<(usize, usize, Tok)>> {
        let start = self.pos;
        let c = match self.peek_char() {
            Some(c) => c,
            None => return Ok(None),
        };
        let tok = match c {
            '\n' => {
                self.pos += 1;
                Tok::Newline
            }
            '\r' => {
                if self.peek_char_at(1) == Some('\n') {
                    self.pos += 2;
                    Tok::Newline
                } else {
                    return Err((start, Kind::Unexpected('\r')));
                }
            }
            ' ' | '\t' => {
                while let Some(' ') | Some('\t') = self.peek_char() {
                    self.pos += 1;
                }
                Tok::Whitespace
            }
            '#' => {
                self.pos += 1;
                while let Some(ch) = self.peek_char() {
                    if ch == '\n' {
                        break;
                    }
                    if ch == '\r' && self.peek_char_at(1) == Some('\n') {
                        break;
                    }
                    if ch != '\t' && (ch as u32) < 0x20 {
                        return Err((self.pos, Kind::Unexpected(ch)));
                    }
                    self.pos += ch.len_utf8();
                }
                Tok::Comment
            }
            '=' => {
                self.pos += 1;
                Tok::Equals
            }
            '.' => {
                self.pos += 1;
                Tok::Period
            }
            ',' => {
                self.pos += 1;
                Tok::Comma
            }
            ':' => {
                self.pos += 1;
                Tok::Colon
            }
            '+' => {
                self.pos += 1;
                Tok::Plus
            }
            '{' => {
                self.pos += 1;
                Tok::LeftBrace
            }
            '}' => {
                self.pos += 1;
                Tok::RightBrace
            }
            '[' => {
                self.pos += 1;
                Tok::LeftBracket
            }
            ']' => {
                self.pos += 1;
                Tok::RightBracket
            }
            '"' => self.basic_string(start)?,
            '\'' => self.literal_string(start)?,
            c if is_keylike(c) => {
                while let Some(ch) = self.peek_char() {
                    if !is_keylike(ch) {
                        break;
                    }
                    self.pos += 1;
                }
                Tok::Keylike(self.input[start..self.pos].to_string())
            }
            c => return Err((start, Kind::Unexpected(c))),
        };
        Ok(Some((start, self.pos, tok)))
    }

    fn literal_string(&mut self, start: usize) -> LResult<Tok> {
        self.pos += 1;
        let multiline = self.input[self.pos..].starts_with("''");
        let mut val = String::new();
        if multiline {
            self.pos += 2;
            if self.input[self.pos..].starts_with('\n') {
                self.pos += 1;
            } else if self.input[self.pos..].starts_with("\r\n") {
                self.pos += 2;
            }
        }
        loop {
            let ch = match self.peek_char() {
                Some(c) => c,
                None => return Err((start, Kind::UnterminatedString)),
            };
            if ch == '\'' {
                if multiline {
                    if self.input[self.pos..].starts_with("'''") {
                        self.pos += 3;
                        // Allow up to two extra quotes.
                        for _ in 0..2 {
                            if self.input[self.pos..].starts_with('\'') {
                                val.push('\'');
                                self.pos += 1;
                            }
                        }
                        return Ok(Tok::Str { val, multiline, literal: true });
                    }
                    val.push('\'');
                    self.pos += 1;
                    continue;
                }
                self.pos += 1;
                return Ok(Tok::Str { val, multiline, literal: true });
            }
            if ch == '\n' && !multiline {
                return Err((self.pos, Kind::NewlineInString));
            }
            if ch == '\r' && multiline && self.peek_char_at(1) == Some('\n') {
                self.pos += 2;
                val.push('\n');
                continue;
            }
            if ch != '\t' && ch != '\n' && ((ch as u32) < 0x20 || ch == '\u{7f}') {
                return Err((self.pos, Kind::InvalidCharInString(ch)));
            }
            val.push(ch);
            self.pos += ch.len_utf8();
        }
    }

    fn basic_string(&mut self, start: usize) -> LResult<Tok> {
        self.pos += 1;
        let multiline = self.input[self.pos..].starts_with("\"\"");
        let mut val = String::new();
        if multiline {
            self.pos += 2;
            if self.input[self.pos..].starts_with('\n') {
                self.pos += 1;
            } else if self.input[self.pos..].starts_with("\r\n") {
                self.pos += 2;
            }
        }
        loop {
            let ch = match self.peek_char() {
                Some(c) => c,
                None => return Err((start, Kind::UnterminatedString)),
            };
            match ch {
                '"' => {
                    if multiline {
                        if self.input[self.pos..].starts_with("\"\"\"") {
                            self.pos += 3;
                            for _ in 0..2 {
                                if self.input[self.pos..].starts_with('"') {
                                    val.push('"');
                                    self.pos += 1;
                                }
                            }
                            return Ok(Tok::Str { val, multiline, literal: false });
                        }
                        val.push('"');
                        self.pos += 1;
                        continue;
                    }
                    self.pos += 1;
                    return Ok(Tok::Str { val, multiline, literal: false });
                }
                '\\' => {
                    self.pos += 1;
                    let esc_pos = self.pos;
                    let e = match self.peek_char() {
                        Some(e) => e,
                        None => return Err((start, Kind::UnterminatedString)),
                    };
                    match e {
                        '"' => val.push('"'),
                        '\\' => val.push('\\'),
                        'b' => val.push('\u{8}'),
                        'f' => val.push('\u{c}'),
                        'n' => val.push('\n'),
                        'r' => val.push('\r'),
                        't' => val.push('\t'),
                        'u' | 'U' => {
                            let len = if e == 'u' { 4 } else { 8 };
                            self.pos += 1;
                            let mut n: u32 = 0;
                            for _ in 0..len {
                                let h = match self.peek_char() {
                                    Some(h) => h,
                                    None => return Err((start, Kind::UnterminatedString)),
                                };
                                match h.to_digit(16) {
                                    Some(d) => n = n * 16 + d,
                                    None => return Err((self.pos, Kind::InvalidHexEscape(h))),
                                }
                                self.pos += 1;
                            }
                            match char::from_u32(n) {
                                Some(c) => val.push(c),
                                None => return Err((esc_pos, Kind::InvalidEscapeValue(n))),
                            }
                            continue;
                        }
                        ' ' | '\t' | '\n' | '\r' if multiline => {
                            // Line ending backslash: skip whitespace and newlines.
                            let mut p = self.pos;
                            let rest = &self.input[p..];
                            let ws_end = rest
                                .find(|c: char| c != ' ' && c != '\t')
                                .unwrap_or(rest.len());
                            let after = &rest[ws_end..];
                            if !(after.starts_with('\n') || after.starts_with("\r\n")) {
                                return Err((esc_pos, Kind::InvalidEscape(e)));
                            }
                            p += ws_end;
                            let rest = &self.input[p..];
                            let skip = rest
                                .find(|c: char| !c.is_whitespace())
                                .unwrap_or(rest.len());
                            self.pos = p + skip;
                            continue;
                        }
                        other => return Err((esc_pos, Kind::InvalidEscape(other))),
                    }
                    self.pos += e.len_utf8();
                }
                '\n' if !multiline => return Err((self.pos, Kind::NewlineInString)),
                '\r' if multiline && self.peek_char_at(1) == Some('\n') => {
                    self.pos += 2;
                    val.push('\n');
                }
                c if c != '\t' && c != '\n' && ((c as u32) < 0x20 || c == '\u{7f}') => {
                    return Err((self.pos, Kind::InvalidCharInString(c)));
                }
                c => {
                    val.push(c);
                    self.pos += c.len_utf8();
                }
            }
        }
    }
}

struct Parser<'a> {
    input: &'a str,
    lexer: Lexer<'a>,
    peeked: Option<Option<(usize, usize, Tok)>>,
}

type PResult<T> = Result<T, TomlError>;

pub fn to_linecol(input: &str, offset: usize) -> (usize, usize) {
    let mut cur = 0;
    for (i, line) in input.split_terminator('\n').enumerate() {
        if cur + line.len() + 1 > offset {
            return (i, offset - cur);
        }
        cur += line.len() + 1;
    }
    (input.lines().count(), 0)
}

pub fn make_error(input: &str, at: usize, kind: Kind, message: String, key: Vec<String>) -> TomlError {
    let (line, col) = to_linecol(input, at);
    TomlError {
        kind,
        line: Some(line),
        col,
        at: Some(at),
        message,
        key,
    }
}

impl<'a> Parser<'a> {
    fn err(&self, at: usize, kind: Kind) -> TomlError {
        make_error(self.input, at, kind, String::new(), Vec::new())
    }

    fn current(&self) -> usize {
        match &self.peeked {
            Some(Some((s, _, _))) => *s,
            _ => self.lexer.pos,
        }
    }

    fn peek(&mut self) -> PResult<Option<(usize, usize, Tok)>> {
        if self.peeked.is_none() {
            let t = self.lexer.next().map_err(|(at, k)| self.err(at, k))?;
            self.peeked = Some(t);
        }
        Ok(self.peeked.clone().unwrap())
    }

    fn next(&mut self) -> PResult<Option<(usize, usize, Tok)>> {
        let t = self.peek()?;
        self.peeked = None;
        Ok(t)
    }

    fn eat(&mut self, tok: &Tok) -> PResult<bool> {
        match self.peek()? {
            Some((_, _, t)) if &t == tok => {
                self.next()?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    fn eat_whitespace(&mut self) -> PResult<()> {
        while self.eat(&Tok::Whitespace)? {}
        Ok(())
    }

    fn eat_comment(&mut self) -> PResult<bool> {
        if self.eat(&Tok::Comment)? {
            self.eat_newline_or_eof()?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn eat_newline_or_eof(&mut self) -> PResult<()> {
        let at = self.current();
        match self.next()? {
            None | Some((_, _, Tok::Newline)) => Ok(()),
            Some((_, _, t)) => Err(self.err(
                at,
                Kind::Wanted {
                    expected: "newline",
                    found: t.describe(),
                },
            )),
        }
    }

    fn expect(&mut self, tok: Tok, expected: &'static str) -> PResult<()> {
        let at = self.current();
        match self.next()? {
            Some((_, _, t)) if t == tok => Ok(()),
            Some((_, _, t)) => Err(self.err(
                at,
                Kind::Wanted {
                    expected,
                    found: t.describe(),
                },
            )),
            None => Err(self.err(
                at,
                Kind::Wanted {
                    expected,
                    found: "eof",
                },
            )),
        }
    }

    fn table_key(&mut self) -> PResult<(usize, String)> {
        let at = self.current();
        match self.next()? {
            Some((s, _, Tok::Keylike(k))) => Ok((s, k)),
            Some((s, _, Tok::Str { val, multiline, .. })) => {
                if multiline {
                    return Err(self.err(s, Kind::MultilineStringKey));
                }
                Ok((s, val))
            }
            Some((_, _, t)) => Err(self.err(
                at,
                Kind::Wanted {
                    expected: "a table key",
                    found: t.describe(),
                },
            )),
            None => Err(self.err(
                at,
                Kind::Wanted {
                    expected: "a table key",
                    found: "eof",
                },
            )),
        }
    }

    fn dotted_key(&mut self) -> PResult<Vec<String>> {
        let mut result = vec![self.table_key()?.1];
        self.eat_whitespace()?;
        while self.eat(&Tok::Period)? {
            self.eat_whitespace()?;
            result.push(self.table_key()?.1);
            self.eat_whitespace()?;
        }
        Ok(result)
    }

    fn value(&mut self) -> PResult<Spanned> {
        let at = self.current();
        match self.next()? {
            Some((s, _, Tok::Str { val, .. })) => Ok(Spanned {
                value: Value::String(val),
                start: Some(s),
            }),
            Some((s, _, Tok::Keylike(k))) if k == "true" => Ok(Spanned {
                value: Value::Boolean(true),
                start: Some(s),
            }),
            Some((s, _, Tok::Keylike(k))) if k == "false" => Ok(Spanned {
                value: Value::Boolean(false),
                start: Some(s),
            }),
            Some((s, _, Tok::Keylike(k))) => {
                if k == "inf" || k == "nan" {
                    return self.number_or_date(s, &k);
                }
                match k.chars().next() {
                    Some('-') | Some('0'..='9') => self.number_or_date(s, &k),
                    _ => Err(self.err(at, Kind::UnquotedString)),
                }
            }
            Some((s, _, Tok::Plus)) => {
                let at2 = self.current();
                match self.next()? {
                    Some((_, _, Tok::Keylike(k))) => {
                        let v = self.number_or_date(s, &k)?;
                        Ok(v)
                    }
                    _ => Err(self.err(at2, Kind::NumberInvalid)),
                }
            }
            Some((s, _, Tok::LeftBrace)) => {
                let t = self.inline_table()?;
                Ok(Spanned {
                    value: Value::Table(t),
                    start: Some(s),
                })
            }
            Some((_, _, Tok::LeftBracket)) => {
                let a = self.array()?;
                Ok(Spanned {
                    value: Value::Array(a),
                    start: None,
                })
            }
            Some((_, _, t)) => Err(self.err(
                at,
                Kind::Wanted {
                    expected: "a value",
                    found: t.describe(),
                },
            )),
            None => Err(self.err(self.input.len(), Kind::UnexpectedEof)),
        }
    }

    fn number_or_date(&mut self, start: usize, s: &str) -> PResult<Spanned> {
        let looks_date = s.contains('T')
            || s.contains('t')
            || (s.len() > 1 && s[1..].contains('-') && !s.contains("e-") && !s.contains("E-"));
        if looks_date {
            return self.datetime(start, s, false);
        }
        if self.eat(&Tok::Colon)? {
            return self.datetime(start, s, true);
        }
        self.number(start, s)
    }

    fn datetime(&mut self, start: usize, s: &str, colon_eaten: bool) -> PResult<Spanned> {
        // Accept the remainder of a datetime loosely.
        let mut text = s.to_string();
        if colon_eaten {
            text.push(':');
        }
        loop {
            match self.peek()? {
                Some((_, _, Tok::Keylike(k))) => {
                    text.push_str(&k);
                    self.next()?;
                }
                Some((_, _, Tok::Colon)) => {
                    text.push(':');
                    self.next()?;
                }
                Some((_, _, Tok::Period)) => {
                    text.push('.');
                    self.next()?;
                }
                Some((_, _, Tok::Plus)) => {
                    text.push('+');
                    self.next()?;
                }
                _ => break,
            }
        }
        let valid = text.len() >= 5 && text.chars().next().map_or(false, |c| c.is_ascii_digit());
        if !valid {
            return Err(self.err(start, Kind::DateInvalid));
        }
        Ok(Spanned {
            value: Value::Datetime(text),
            start: Some(start),
        })
    }

    fn number(&mut self, start: usize, s: &str) -> PResult<Spanned> {
        let int = |v: i64| Spanned {
            value: Value::Integer(v),
            start: Some(start),
        };
        let float = |v: f64| Spanned {
            value: Value::Float(v),
            start: Some(start),
        };
        if let Some(r) = s.strip_prefix("0x") {
            return self.integer(start + 2, r, 16).map(int);
        }
        if let Some(r) = s.strip_prefix("0o") {
            return self.integer(start + 2, r, 8).map(int);
        }
        if let Some(r) = s.strip_prefix("0b") {
            return self.integer(start + 2, r, 2).map(int);
        }
        if s.contains('e') || s.contains('E') {
            return self.float(start, s, None).map(float);
        }
        if self.eat(&Tok::Period)? {
            let at = self.current();
            return match self.next()? {
                Some((_, _, Tok::Keylike(after))) => self.float(start, s, Some(&after)).map(float),
                _ => Err(self.err(at, Kind::NumberInvalid)),
            };
        }
        match s {
            "inf" | "+inf" => return Ok(float(f64::INFINITY)),
            "-inf" => return Ok(float(f64::NEG_INFINITY)),
            "nan" | "+nan" | "-nan" => return Ok(float(f64::NAN)),
            _ => {}
        }
        self.integer(start, s, 10).map(int)
    }

    fn parse_integer<'s>(
        &self,
        start: usize,
        s: &'s str,
        allow_sign: bool,
        allow_leading_zeros: bool,
        radix: u32,
    ) -> PResult<(&'s str, &'s str)> {
        let mut first = true;
        let mut first_zero = false;
        let mut underscore = false;
        let mut end = s.len();
        for (i, c) in s.char_indices() {
            let at = i + start;
            if i == 0 && (c == '+' || c == '-') && allow_sign {
                continue;
            }
            if c == '0' && first {
                first_zero = true;
            } else if c.is_digit(radix) {
                if !first && first_zero && !allow_leading_zeros {
                    return Err(self.err(at, Kind::NumberInvalid));
                }
                underscore = false;
            } else if c == '_' && first {
                return Err(self.err(at, Kind::NumberInvalid));
            } else if c == '_' && !underscore {
                underscore = true;
            } else {
                end = i;
                break;
            }
            first = false;
        }
        if first || underscore {
            return Err(self.err(start, Kind::NumberInvalid));
        }
        Ok((&s[..end], &s[end..]))
    }

    fn integer(&self, start: usize, s: &str, radix: u32) -> PResult<i64> {
        let allow_sign = radix == 10;
        let allow_leading_zeros = radix != 10;
        let (prefix, suffix) = self.parse_integer(start, s, allow_sign, allow_leading_zeros, radix)?;
        if !suffix.is_empty() {
            return Err(self.err(start, Kind::NumberInvalid));
        }
        i64::from_str_radix(prefix.replace('_', "").trim_start_matches('+'), radix)
            .map_err(|_| self.err(start, Kind::NumberInvalid))
    }

    fn float(&mut self, start: usize, s: &str, after_decimal: Option<&str>) -> PResult<f64> {
        let (integral, mut suffix) = self.parse_integer(start, s, true, false, 10)?;
        let mut fraction = None;
        if let Some(after) = after_decimal {
            if !suffix.is_empty() {
                return Err(self.err(start, Kind::NumberInvalid));
            }
            let (a, b) = self.parse_integer(start, after, false, true, 10)?;
            fraction = Some(a);
            suffix = b;
        }
        let mut exponent = None;
        if suffix.starts_with('e') || suffix.starts_with('E') {
            let (a, b) = if suffix.len() == 1 {
                self.eat(&Tok::Plus)?;
                let at = self.current();
                match self.next()? {
                    Some((_, _, Tok::Keylike(s2))) => {
                        let s2: &str = Box::leak(s2.into_boxed_str());
                        self.parse_integer(at, s2, false, true, 10)?
                    }
                    _ => return Err(self.err(start, Kind::NumberInvalid)),
                }
            } else {
                let rest = &suffix[1..];
                self.parse_integer(start, rest, true, true, 10)?
            };
            if !b.is_empty() {
                return Err(self.err(start, Kind::NumberInvalid));
            }
            exponent = Some(a);
        } else if !suffix.is_empty() {
            return Err(self.err(start, Kind::NumberInvalid));
        }
        let mut number = integral.trim_start_matches('+').chars().filter(|c| *c != '_').collect::<String>();
        if let Some(f) = fraction {
            number.push('.');
            number.extend(f.chars().filter(|c| *c != '_'));
        }
        if let Some(e) = exponent {
            number.push('E');
            number.extend(e.chars().filter(|c| *c != '_'));
        }
        number
            .parse::<f64>()
            .map_err(|_| self.err(start, Kind::NumberInvalid))
            .and_then(|n| {
                if n.is_finite() {
                    Ok(n)
                } else {
                    Err(self.err(start, Kind::NumberInvalid))
                }
            })
    }

    fn eat_intermediate(&mut self) -> PResult<()> {
        loop {
            self.eat_whitespace()?;
            if !self.eat(&Tok::Newline)? && !self.eat_comment()? {
                break;
            }
        }
        Ok(())
    }

    fn array(&mut self) -> PResult<Vec<Value>> {
        let mut ret = Vec::new();
        loop {
            self.eat_intermediate()?;
            if self.eat(&Tok::RightBracket)? {
                return Ok(ret);
            }
            let v = self.value()?;
            ret.push(v.value);
            self.eat_intermediate()?;
            if !self.eat(&Tok::Comma)? {
                break;
            }
        }
        self.eat_intermediate()?;
        self.expect(Tok::RightBracket, "a right bracket")?;
        Ok(ret)
    }

    fn inline_table(&mut self) -> PResult<Vec<(String, Value)>> {
        let mut ret: Vec<(String, Value)> = Vec::new();
        self.eat_whitespace()?;
        if self.eat(&Tok::RightBrace)? {
            return Ok(ret);
        }
        loop {
            let key = self.dotted_key()?;
            self.eat_whitespace()?;
            self.expect(Tok::Equals, "an equals")?;
            self.eat_whitespace()?;
            let v = self.value()?;
            ret.push((key.join("."), v.value));
            self.eat_whitespace()?;
            if self.eat(&Tok::RightBrace)? {
                return Ok(ret);
            }
            self.expect(Tok::Comma, "a comma")?;
            self.eat_whitespace()?;
        }
    }
}

pub struct Document {
    /// Top-level key/value pairs (in order).
    pub top: Vec<(String, Spanned)>,
    /// Names of tables declared via headers whose first key segment matters.
    pub headers: Vec<(Vec<String>, bool, usize)>,
}

pub fn parse(input: &str) -> Result<Document, TomlError> {
    let mut p = Parser {
        input,
        lexer: Lexer { input, pos: 0 },
        peeked: None,
    };
    let mut doc = Document {
        top: Vec::new(),
        headers: Vec::new(),
    };
    let mut in_table = false;
    let mut seen_tables: Vec<Vec<String>> = Vec::new();
    loop {
        loop {
            p.eat_whitespace()?;
            if p.eat_comment()? {
                continue;
            }
            if p.eat(&Tok::Newline)? {
                continue;
            }
            break;
        }
        match p.peek()? {
            None => break,
            Some((start, _, Tok::LeftBracket)) => {
                p.next()?;
                let array = p.eat(&Tok::LeftBracket)?;
                p.eat_whitespace()?;
                let mut name = vec![p.table_key()?.1];
                p.eat_whitespace()?;
                while p.eat(&Tok::Period)? {
                    p.eat_whitespace()?;
                    name.push(p.table_key()?.1);
                    p.eat_whitespace()?;
                }
                p.expect(Tok::RightBracket, "a right bracket")?;
                if array {
                    p.expect(Tok::RightBracket, "a right bracket")?;
                }
                p.eat_whitespace()?;
                if !p.eat_comment()? {
                    p.eat_newline_or_eof()?;
                }
                if !array {
                    if seen_tables.contains(&name) {
                        let (line, col) = to_linecol(input, start);
                        return Err(TomlError {
                            kind: Kind::DuplicateTable(name.join(".")),
                            line: Some(line),
                            col,
                            at: Some(start),
                            message: String::new(),
                            key: name.clone(),
                        });
                    }
                    seen_tables.push(name.clone());
                }
                doc.headers.push((name, array, start));
                in_table = true;
            }
            Some(_) => {
                let key = p.dotted_key()?;
                p.eat_whitespace()?;
                p.expect(Tok::Equals, "an equals")?;
                p.eat_whitespace()?;
                let value = p.value()?;
                p.eat_whitespace()?;
                if !p.eat_comment()? {
                    p.eat_newline_or_eof()?;
                }
                if !in_table {
                    if key.len() == 1 {
                        doc.top.push((key[0].clone(), value));
                    } else {
                        doc.top.push((
                            key[0].clone(),
                            Spanned {
                                value: Value::Table(Vec::new()),
                                start: None,
                            },
                        ));
                    }
                }
            }
        }
    }
    Ok(doc)
}

pub fn unexpected(v: &Value) -> String {
    match v {
        Value::String(s) => format!("string {:?}", s),
        Value::Integer(i) => format!("integer `{}`", i),
        Value::Float(f) => {
            if f.fract() == 0.0 && f.is_finite() {
                format!("floating point `{:.1}`", f)
            } else {
                format!("floating point `{}`", f)
            }
        }
        Value::Boolean(b) => format!("boolean `{}`", b),
        Value::Datetime(_) => "map".to_string(),
        Value::Array(_) => "sequence".to_string(),
        Value::Table(_) => "map".to_string(),
    }
}
