//! Loading of the `handlr.toml` configuration file.

use std::fs;
use std::io::{Read, Write};

use crate::panic::fake_panic;
use crate::toml::{self, Kind, TomlError, Value};
use crate::xdg;

const PANIC_LOCATION: &str = "src/config.rs:63:31";

pub const DEFAULT_SELECTOR: &str = "rofi -dmenu -i -p 'Open With: '";

#[derive(Clone, Debug)]
pub struct Config {
    pub enable_selector: bool,
    pub selector: String,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            enable_selector: false,
            selector: DEFAULT_SELECTOR.to_string(),
        }
    }
}

fn serialize_default() -> String {
    format!(
        "enable_selector = false\nselector = \"{}\"\n",
        DEFAULT_SELECTOR
    )
}

fn custom(input: &str, at: Option<usize>, message: String, key: Vec<String>) -> TomlError {
    toml::make_error(input, at.unwrap_or(0), Kind::Custom, message, key)
}

fn parse_config(input: &str) -> Result<Config, TomlError> {
    let doc = toml::parse(input)?;
    let mut fields: Vec<(String, toml::Spanned)> = doc.top.clone();
    let mut seen_header_roots: Vec<String> = Vec::new();
    for (name, array, _) in &doc.headers {
        let root = name[0].clone();
        if fields.iter().any(|(k, _)| *k == root) || seen_header_roots.contains(&root) {
            continue;
        }
        seen_header_roots.push(root.clone());
        let value = if *array && name.len() == 1 {
            Value::Array(Vec::new())
        } else {
            Value::Table(Vec::new())
        };
        fields.push((root, toml::Spanned { value, start: None }));
    }
    let mut cfg = Config::default();
    let mut seen_enable = false;
    let mut seen_selector = false;
    for (key, spanned) in fields {
        match key.as_str() {
            "enable_selector" => {
                if seen_enable {
                    return Err(custom(
                        input,
                        None,
                        "duplicate field `enable_selector`".into(),
                        Vec::new(),
                    ));
                }
                seen_enable = true;
                match spanned.value {
                    Value::Boolean(b) => cfg.enable_selector = b,
                    ref v => {
                        return Err(custom(
                            input,
                            spanned.start,
                            format!("invalid type: {}, expected a boolean", toml::unexpected(v)),
                            vec![key.clone()],
                        ))
                    }
                }
            }
            "selector" => {
                if seen_selector {
                    return Err(custom(
                        input,
                        None,
                        "duplicate field `selector`".into(),
                        Vec::new(),
                    ));
                }
                seen_selector = true;
                match spanned.value {
                    Value::String(ref s) => cfg.selector = s.clone(),
                    ref v => {
                        return Err(custom(
                            input,
                            spanned.start,
                            format!("invalid type: {}, expected a string", toml::unexpected(v)),
                            vec![key.clone()],
                        ))
                    }
                }
            }
            _ => {}
        }
    }
    Ok(cfg)
}

fn fail(msg: String) -> ! {
    fake_panic(
        PANIC_LOCATION,
        &format!("called `Result::unwrap()` on an `Err` value: {}", msg),
    )
}

pub fn load() -> Config {
    let dir = xdg::config_home().join("handlr");
    let path = dir.join("handlr.toml");
    match fs::File::open(&path) {
        Ok(mut f) => {
            let mut s = String::new();
            if let Err(e) = f.read_to_string(&mut s) {
                fail(format!("ReadConfigurationFileError({:?})", e));
            }
            match parse_config(&s) {
                Ok(c) => c,
                Err(e) => fail(format!("BadTomlData({:?})", e)),
            }
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if let Err(e) = fs::create_dir_all(&dir) {
                fail(format!("DirectoryCreationFailed({:?})", e));
            }
            let mut f = match fs::OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&path)
            {
                Ok(f) => f,
                Err(e) => fail(format!("OpenConfigurationFileError({:?})", e)),
            };
            if let Err(e) = f.write_all(serialize_default().as_bytes()) {
                fail(format!("WriteConfigurationFileError({:?})", e));
            }
            Config::default()
        }
        Err(e) => fail(format!("GeneralLoadError({:?})", e)),
    }
}
