use crate::mimeapps_grammar::ParseError;

pub enum Error {
    Io(std::io::Error),
    ParseApps(ParseError),
    BadMime(MimeError),
    BadMimeType(Mime),
    Ambiguous(String),
    NotFound(String),
    BadEntry(PathBuf),
    NoTerminal,
    BadPath(String),
    Cancelled,
}

pub type Result<T> = std::result::Result<T, Error>;

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::Io(e)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(e) => write!(f, "{}", e),
            Error::ParseApps(e) => write!(f, "{:?}", e),
            Error::BadMime(e) => write!(f, "mime parse error: {}", e),
            Error::BadMimeType(m) => write!(f, "bad mime: {}", m),
            Error::Ambiguous(s) => write!(f, "could not figure out the mime type of '{}'", s),
