                f,
                "Please specify the default terminal with handlr set x-scheme-handler/terminal"
            ),
            Error::BadPath(s) => write!(f, "Bad path: {}", s),
            Error::Cancelled => write!(f, "Selection cancelled"),
        }
    }
}

impl fmt::Debug for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(e) => write!(f, "Io({:?})", e),
            Error::ParseApps(e) => write!(f, "ParseApps({:?})", e),
            Error::BadMime(e) => write!(f, "BadMime({:?})", e),
            Error::BadMimeType(m) => write!(f, "BadMimeType({:?})", m.as_str()),
            Error::Ambiguous(s) => write!(f, "Ambiguous({:?})", s),
            Error::NotFound(s) => write!(f, "NotFound({:?})", s),
            Error::BadEntry(p) => write!(f, "BadEntry({:?})", p),
            Error::NoTerminal => write!(f, "NoTerminal"),
            Error::BadPath(s) => write!(f, "BadPath({:?})", s),
            Error::Cancelled => write!(f, "Cancelled"),
        }
    }
}
