//! Desktop entries and handlers.

use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use crate::apps::MimeApps;
use crate::config::Config;
use crate::desktop_parser;
use crate::error::{Error, Result};
use crate::mime::Mime;
use crate::panic::fake_panic;
use crate::shlex;
use crate::xdg;

#[derive(Clone, Debug)]
pub struct DesktopEntry {
    pub name: String,
    pub exec: String,
    pub file_name: OsString,
    pub mimes: Vec<Mime>,
    pub term: bool,
    pub categories: Vec<String>,
}

impl DesktopEntry {
    pub fn from_path(path: &Path) -> Option<DesktopEntry> {
        let data = fs::read(path).ok()?;
        let groups = desktop_parser::parse(&data)?;
        let group = groups.get("Desktop Entry")?;
        let name = group.get("Name").cloned().unwrap_or_default();
        let exec = group.get("Exec").cloned().unwrap_or_default();
        if name.is_empty() || exec.is_empty() {
            return None;
        }
        let mimes = group
            .get("MimeType")
            .map(|m| m.split(';').filter_map(|s| Mime::parse(s).ok()).collect())
            .unwrap_or_default();
        let term = group.get("Terminal").map(|t| t == "true").unwrap_or(false);
        let categories = group
            .get("Categories")
            .map(|c| c.split(';').map(|s| s.to_string()).collect())
            .unwrap_or_default();
        Some(DesktopEntry {
            name,
            exec,
            file_name: path.file_name().map(|f| f.to_owned()).unwrap_or_default(),
            mimes,
            term,
            categories,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Handler(pub String);

impl Handler {
    fn rel_path(&self) -> PathBuf {
        Path::new("applications").join(&self.0)
    }

    pub fn resolve(name: &str) -> Result<Handler> {
        let h = Handler(name.to_string());
        let path = xdg::find_data_file(&h.rel_path()).ok_or_else(|| Error::NotFound(name.to_string()))?;
        if DesktopEntry::from_path(&path).is_none() {
            return Err(Error::BadEntry(path));
        }
        Ok(h)
    }

    pub fn get_path(&self) -> Result<PathBuf> {
        xdg::find_data_file(&self.rel_path()).ok_or_else(|| Error::NotFound(self.0.clone()))
    }

    pub fn get_entry(&self) -> Result<DesktopEntry> {
        let path = self.get_path()?;
        DesktopEntry::from_path(&path).ok_or(Error::BadEntry(path))
    }
}

pub fn stdout_is_tty() -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(1) == 1 }
}

/// Spawns a desktop notification.
pub fn notify(title: &str, msg: &str) -> std::io::Result<()> {
    Command::new("notify-send")
        .args(["-t", "10000", title, msg])
        .spawn()
        .map(|_| ())
}

#[derive(PartialEq, Eq, Clone, Copy)]
pub enum Mode {
    Launch,
    Open,
}

fn is_field_code(s: &str) -> bool {
    s == "%f" || s == "%F" || s == "%u" || s == "%U"
}

fn find_field_code(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    (0..b.len().saturating_sub(1)).find(|&i| b[i] == b'%' && matches!(b[i + 1], b'f' | b'F' | b'u' | b'U'))
}

pub struct Ctx<'a> {
    pub config: &'a Config,
    pub apps: &'a MimeApps,
}

impl DesktopEntry {
    pub fn get_cmd(&self, ctx: &Ctx, args: Vec<String>) -> Result<(String, Vec<String>)> {
        let mut exec = match shlex::split(&self.exec) {
            Some(v) => v,
            None => fake_panic(
                "src/common/desktop_entry.rs:65:49",
                "called `Option::unwrap()` on a `None` value",
            ),
        };
        if find_field_code(&self.exec).is_some() {
            let joined = args.join(" ");
            let mut out = Vec::new();
            for s in exec {
                if is_field_code(&s) {
                    out.extend(args.iter().cloned());
                } else if let Some(i) = find_field_code(&s) {
                    out.push(format!("{}{}{}", &s[..i], joined, &s[i + 2..]));
                } else {
                    out.push(s);
                }
            }
            exec = out;
        } else {
            exec.extend(args);
        }
        if self.term && !stdout_is_tty() {
            let term = terminal(ctx)?;
            let mut t = match shlex::split(&term) {
                Some(v) => v,
                None => fake_panic(
                    "src/common/desktop_entry.rs:99:58",
                    "called `Option::unwrap()` on a `None` value",
                ),
            };
            t.extend(exec);
            exec = t;
        }
        if exec.is_empty() {
            fake_panic(
                "src/common/desktop_entry.rs:105:18",
                "removal index (is 0) should be < len (is 0)",
            );
        }
        let cmd = exec.remove(0);
        Ok((cmd, exec))
    }

    pub fn exec(&self, ctx: &Ctx, mode: Mode, args: Vec<String>) -> Result<()> {
        let supports_multiple = self.exec.contains("%F") || self.exec.contains("%U");
        if args.is_empty() {
            self.exec_inner(ctx, vec![])
        } else if supports_multiple || mode == Mode::Launch {
            self.exec_inner(ctx, args)
        } else {
            for arg in args {
                self.exec_inner(ctx, vec![arg])?;
            }
            Ok(())
        }
    }

    fn exec_inner(&self, ctx: &Ctx, args: Vec<String>) -> Result<()> {
        let (cmd, args) = self.get_cmd(ctx, args)?;
        let mut command = Command::new(cmd);
        command.args(args);
        if self.term && stdout_is_tty() {
            command.spawn()?.wait()?;
        } else {
            command.stdout(Stdio::null()).stderr(Stdio::null()).spawn()?;
        }
        Ok(())
    }
}

/// All desktop entries from the applications directories, in priority order.
pub fn system_entries() -> Vec<(OsString, DesktopEntry)> {
    let mut out = Vec::new();
    for path in xdg::list_data_files_once("applications") {
        if path.extension().map_or(true, |e| e != "desktop") {
            continue;
        }
        if let Some(entry) = DesktopEntry::from_path(&path) {
            let name = path.file_name().map(|f| f.to_owned()).unwrap_or_default();
            out.push((name, entry));
        }
    }
    out
}

pub fn terminal(ctx: &Ctx) -> Result<String> {
    let term_mime = Mime::known("x-scheme-handler/terminal");
    let entry = ctx
        .apps
        .get_handler(ctx.config, &term_mime)
        .ok()
        .and_then(|h| h.get_entry().ok());
    let entry = entry.or_else(|| {
        let (name, entry) = system_entries()
            .into_iter()
            .find(|(_, e)| e.categories.iter().any(|c| c == "TerminalEmulator"))?;
        notify(
            "handlr",
            &format!(
                "Guessed terminal emulator: {}.\n\nIf this is wrong, use `handlr set x-scheme-handler/terminal` to update it.",
                name.to_string_lossy()
            ),
        )
        .ok()?;
        let mut apps = ctx.apps.clone();
        apps.set_handler(term_mime.clone(), Handler(name.to_string_lossy().into_owned()));
        apps.save().ok()?;
        Some(entry)
    });
    entry
        .map(|e| format!("{} -e", e.exec))
        .ok_or(Error::NoTerminal)
}
EOF"}

