            out.push((name, entry));
        }
    }
    out
}

pub fn terminal(ctx: &Ctx) -> Result<String> {
    let term_mime = Mime::known("x-scheme-handler/terminal");
    let entry = ctx
        .apps
        .get_handler(ctx.config, &term_mime)
        .ok()
        .and_then(|h| h.get_entry().ok());
    let entry = entry.or_else(|| {
        let (name, entry) = system_entries()
            .into_iter()
            .find(|(_, e)| e.categories.iter().any(|c| c == "TerminalEmulator"))?;
