            "handlr",
            &format!(
                "Guessed terminal emulator: {}.\n\nIf this is wrong, use `handlr set x-scheme-handler/terminal` to update it.",
                name.to_string_lossy()
            ),
        )
        .ok()?;
        let mut apps = ctx.apps.clone();
        apps.set_handler(term_mime.clone(), Handler(name.to_string_lossy().into_owned()));
        apps.save().ok()?;
        Some(entry)
    });
