const CLAP_MATCHES_PANIC: &str = "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/matches/arg_matches.rs:220:28";

pub enum UserPath {
    Url(Url),
    File(PathBuf),
}

pub enum Cmd {
    List { all: bool },
    Open { paths: Vec<UserPath> },
    Set { mime: Mime, handler: Handler },
    Unset { mime: Mime },
    Launch { mime: Mime, args: Vec<String> },
    Get { json: bool, mime: Mime },
    Add { mime: Mime, handler: Handler },
}

#[derive(Clone, Copy, PartialEq)]
enum PosKind {
    Mime,
    Handler,
    Path,
    Arg,
}

struct Pos {
    name: &'static str,
    kind: PosKind,
    multiple: bool,
    required: bool,
}

struct Flag {
    name: &'static str,
    long: &'static str,
    short: Option<char>,
    help: &'static str,
}

struct Sub {
    name: &'static str,
    about: &'static str,
    flags: &'static [Flag],
    pos: &'static [Pos],
}

const MIME: Pos = Pos { name: "mime", kind: PosKind::Mime, multiple: false, required: true };
const HANDLER: Pos = Pos { name: "handler", kind: PosKind::Handler, multiple: false, required: true };

static SUBS: &[Sub] = &[
    Sub {
        name: "list",
        about: "List default apps and the associated handlers",
        flags: &[Flag { name: "all", long: "all", short: Some('a'), help: "" }],
        pos: &[],
    },
    Sub {
        name: "open",
        about: "Open a path/URL with its default handler",
        flags: &[],
        pos: &[Pos { name: "paths", kind: PosKind::Path, multiple: true, required: true }],
    },
    Sub {
        name: "set",
        about: "Set the default handler for mime/extension",
        flags: &[],
        pos: &[MIME, HANDLER],
    },
    Sub {
        name: "unset",
        about: "Unset the default handler for mime/extension",
        flags: &[],
        pos: &[MIME],
    },
    Sub {
        name: "launch",
        about: "Launch the handler for specified extension/mime with optional arguments",
        flags: &[],
        pos: &[MIME, Pos { name: "args", kind: PosKind::Arg, multiple: true, required: false }],
    },
    Sub {
        name: "get",
        about: "Get handler for this mime/extension",
        flags: &[Flag { name: "json", long: "json", short: None, help: "" }],
        pos: &[MIME],
    },
    Sub {
        name: "add",
        about: "Add a handler for given mime/extension Note that the first handler is the default",
        flags: &[],
        pos: &[MIME, HANDLER],
    },
];

fn pos_display(p: &Pos, used: bool) -> String {
    let base = if p.required || used {
        format!("<{}>", p.name)
    } else {
        format!("[{}]", p.name)
    };
    if p.multiple {
        format!("{}...", base)
    } else {
        base
    }
}

fn top_help(bin: &str) -> String {
    let mut s = String::new();
    s.push_str("handlr 0.6.4\n\nUSAGE:\n    ");
    s.push_str(bin);
    s.push_str(" <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n");
    for sub in SUBS {
        s.push_str(&format!("    {:<10}{}\n", sub.name, sub.about));
    }
    s
}

fn sub_help_usage(bin: &str, sub: &Sub) -> String {
    let mut s = format!("{} {}", bin, sub.name);
    if !sub.flags.is_empty() {
        s.push_str(" [FLAGS]");
    }
    for p in sub.pos {
        s.push(' ');
        s.push_str(&pos_display(p, false));
    }
    s
}

fn sub_help(bin: &str, sub: &Sub) -> String {
    let mut s = format!("{}-{} \n{}\n\nUSAGE:\n    {}\n", bin, sub.name, sub.about, sub_help_usage(bin, sub));
    if !sub.pos.is_empty() {
        s.push_str("\nARGS:\n");
        let names: Vec<String> = sub.pos.iter().map(|p| pos_display(p, true)).collect();
        let width = names.iter().map(|n| n.len()).max().unwrap_or(0);
        for n in names {
            s.push_str(&format!("    {:<w$}    \n", n, w = width));
        }
    }
    s.push_str("\nFLAGS:\n");
    for f in sub.flags {
        let left = match f.short {
            Some(c) => format!("-{}, --{}", c, f.long),
            None => format!("    --{}", f.long),
        };
        s.push_str(&format!("    {:<17}{}\n", left, f.help));
    }
    s.push_str("    -h, --help       Prints help information\n");
    s.push_str("    -V, --version    Prints version information\n");
    s
}

fn print_and_exit(text: &str, to_stderr: bool, code: i32) -> ! {
    use std::io::Write;
    if to_stderr {
        let mut e = std::io::stderr();
        let _ = e.write_all(text.as_bytes());
        let _ = e.flush();
    } else {
        let mut o = std::io::stdout();
        let _ = o.write_all(text.as_bytes());
        let _ = o.flush();
    }
    exit(code)
}

fn error_exit(msg: &str) -> ! {
    print_and_exit(&format!("error: {}\n", msg), true, 2)
}

fn unknown_argument(arg: &str, suggestion: &str, usage: &str) -> ! {
    error_exit(&format!(
        "Found argument '{arg}' which wasn't expected, or isn't valid in this context{suggestion}\n\nIf you tried to supply `{arg}` as a PATTERN use `-- {arg}`\n\nUSAGE:\n    {usage}\n\nFor more information try --help",
        arg = arg,
        suggestion = suggestion,
        usage = usage
    ))
}

fn lossy(s: &OsStr) -> String {
    s.to_string_lossy().into_owned()
}

pub fn bin_name(argv0: Option<&OsString>) -> String {
    match argv0 {
        Some(a) => {
            let p = std::path::Path::new(a);
            match p.file_name() {
                Some(f) => f.to_string_lossy().into_owned(),
                None => a.to_string_lossy().into_owned(),
            }
        }
        None => "handlr".to_string(),
    }
}

pub fn parse(args: Vec<OsString>, db: &dyn Fn() -> MimeDb) -> Cmd {
    let bin = bin_name(args.first());
    let rest: Vec<OsString> = args.into_iter().skip(1).collect();
    if rest.is_empty() {
        print_and_exit(&top_help(&bin), true, 2);
    }
    let mut i = 0;
    while i < rest.len() {
        let raw = &rest[i];
        let bytes = raw.as_encoded_bytes();
        if bytes == b"--" {
            if i + 1 < rest.len() {
                unknown_argument(&lossy(&rest[i + 1]), "", &format!("{} <SUBCOMMAND>", bin));
            }
            print_and_exit(&top_help(&bin), true, 2);
        }
        if bytes.starts_with(b"--") {
            let s = match raw.to_str() {
                Some(s) => s,
                None => fake_panic(CLAP_PARSER_PANIC, "unexpected invalid UTF-8 code point"),
            };
            let name = s[2..].split('=').next().unwrap_or("");
            match name {
                "help" => print_and_exit(&top_help(&bin), false, 0),
                "version" => print_and_exit("handlr 0.6.4\n", false, 0),
                _ => {}
            }
            let arg = format!("--{}", name);
            if let Some(c) = did_you_mean(name, &["help", "version"]) {
                unknown_argument(
                    &arg,
                    &format!("\n\n\tDid you mean '--{}'?", c),
                    &format!("{} --{}", bin, c),
                );
            }
            for sub in SUBS {
                let mut longs: Vec<&str> = sub.flags.iter().map(|f| f.long).collect();
                longs.push("help");
                longs.push("version");
                if let Some(c) = did_you_mean(name, &longs) {
                    unknown_argument(
                        &arg,
                        &format!("\n\n\tDid you mean to put '--{}' after the subcommand '{}'?", c, sub.name),
                        &format!("{} <SUBCOMMAND>", bin),
                    );
                }
            }
            unknown_argument(&arg, "", &format!("{} <SUBCOMMAND>", bin));
        }
        if bytes.starts_with(b"-") && bytes.len() > 1 {
            let s = lossy(raw);
            for c in s[1..].chars() {
                match c {
                    'h' => print_and_exit(&top_help(&bin), false, 0),
                    'V' => print_and_exit("handlr 0.6.4\n", false, 0),
                    _ => unknown_argument(&format!("-{}", c), "", &format!("{} <SUBCOMMAND>", bin)),
                }
            }
            i += 1;
            continue;
        }
        let s = lossy(raw);
        if let Some(sub) = SUBS.iter().find(|sub| sub.name == s) {
            return parse_sub(&bin, sub, &rest[i + 1..], db);
        }
        let names: Vec<&str> = SUBS.iter().map(|s| s.name).collect();
        if let Some(c) = did_you_mean(&s, &names) {
            error_exit(&format!(
                "The subcommand '{s}' wasn't recognized\n\n\tDid you mean '{c}'?\n\nIf you believe you received this message in error, try re-running with '{bin} -- {s}'\n\nUSAGE:\n    {bin} <SUBCOMMAND>\n\nFor more information try --help",
                s = s,
                c = c,
                bin = bin
            ));
        }
        unknown_argument(&s, "", &format!("{} <SUBCOMMAND>", bin));
    }
    print_and_exit(&top_help(&bin), true, 2)
}

#[derive(Clone, PartialEq)]
enum Used {
    Flag(&'static str),
    Pos(usize),
}

fn smart_usage(bin: &str, sub: &Sub, used: &[Used]) -> String {
    // Used arguments that are not required.
    let extra: Vec<&Used> = used
        .iter()
        .filter(|u| match u {
            Used::Flag(_) => true,
            Used::Pos(i) => !sub.pos[*i].required,
        })
        .collect();
    if extra.is_empty() {
        return sub_help_usage(bin, sub);
    }
    let mut s = format!("{} {}", bin, sub.name);
    for (idx, p) in sub.pos.iter().enumerate() {
        if p.required || used.contains(&Used::Pos(idx)) {
            s.push(' ');
            s.push_str(&pos_display(p, true));
        }
    }
    for u in &extra {
        if let Used::Flag(name) = u {
            s.push_str(&format!(" --{}", name));
        }
    }
    s
}

fn flag_long_for(sub: &Sub, name: &str) -> &'static str {
    match name {
        "help" => "help",
        "version" => "version",
        _ => sub.flags.iter().find(|f| f.name == name).map(|f| f.long).unwrap_or("help"),
    }
}

fn parse_sub(bin: &str, sub: &Sub, args: &[OsString], db: &dyn Fn() -> MimeDb) -> Cmd {
    let mut used: Vec<Used> = Vec::new();
    let mut flags_present: Vec<&'static str> = Vec::new();
    let mut values: Vec<Vec<OsString>> = sub.pos.iter().map(|_| Vec::new()).collect();
    let mut pos_index = 0usize;
    let mut trailing = false;

    let mut set_flag = |flag: &'static Flag, used: &mut Vec<Used>, flags_present: &mut Vec<&'static str>| {
        if flags_present.contains(&flag.name) {
            error_exit(&format!(
                "The argument '--{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help",
                flag.long,
                sub_help_usage(bin, sub)
            ));
        }
        flags_present.push(flag.name);
        used.push(Used::Flag(flag.name));
    };

    for raw in args {
        let bytes = raw.as_encoded_bytes();
        if !trailing {
            if bytes == b"--" {
                trailing = true;
                continue;
            }
            if bytes.starts_with(b"--") {
                let s = match raw.to_str() {
                    Some(s) => s,
                    None => fake_panic(CLAP_PARSER_PANIC, "unexpected invalid UTF-8 code point"),
                };
                let name = s[2..].split('=').next().unwrap_or("");
                if name == "help" {
                    print_and_exit(&sub_help(bin, sub), false, 0);
                }
                if name == "version" {
                    print_and_exit(&format!("{}-{} \n", bin, sub.name), false, 0);
                }
                if let Some(flag) = sub.flags.iter().find(|f| f.long == name) {
                    set_flag(flag, &mut used, &mut flags_present);
                    continue;
                }
                let mut longs: Vec<&str> = sub.flags.iter().map(|f| f.long).collect();
                longs.push("help");
                longs.push("version");
                let arg = format!("--{}", name);
                if let Some(c) = did_you_mean(name, &longs) {
                    let fname: &'static str = match c {
                        "help" => "help",
                        "version" => "version",
                        other => sub.flags.iter().find(|f| f.long == other).map(|f| f.name).unwrap_or("help"),
                    };
                    let mut u = used.clone();
                    if !u.contains(&Used::Flag(fname)) {
                        u.push(Used::Flag(fname));
                    }
                    let usage = smart_usage_named(bin, sub, &u);
                    unknown_argument(&arg, &format!("\n\n\tDid you mean '--{}'?", c), &usage);
                }
                let usage = smart_usage_named(bin, sub, &used);
                unknown_argument(&arg, "", &usage);
            }
            if bytes.starts_with(b"-") && bytes.len() > 1 {
                let s = lossy(raw);
                for c in s[1..].chars() {
                    if c == 'h' {
                        print_and_exit(&sub_help(bin, sub), false, 0);
                    }
                    if c == 'V' {
                        print_and_exit(&format!("{}-{} \n", bin, sub.name), false, 0);
                    }
                    if let Some(flag) = sub.flags.iter().find(|f| f.short == Some(c)) {
                        set_flag(flag, &mut used, &mut flags_present);
                        continue;
                    }
                    unknown_argument(&format!("-{}", c), "", &sub_help_usage(bin, sub));
                }
                continue;
            }
        }
        if pos_index < sub.pos.len() {
            if values[pos_index].is_empty() {
                used.push(Used::Pos(pos_index));
            }
            values[pos_index].push(raw.clone());
            if !sub.pos[pos_index].multiple {
                pos_index += 1;
            }
        } else {
            unknown_argument(&lossy(raw), "", &sub_help_usage(bin, sub));
        }
    }

    // Required arguments.
    let missing: Vec<String> = sub
        .pos
        .iter()
        .enumerate()
        .filter(|(i, p)| p.required && values[*i].is_empty())
        .map(|(_, p)| pos_display(p, true))
        .collect();
    if !missing.is_empty() {
        let list: String = missing.iter().map(|m| format!("\n    {}", m)).collect();
        error_exit(&format!(
            "The following required arguments were not provided:{}\n\nUSAGE:\n    {}\n\nFor more information try --help",
            list,
            smart_usage_named(bin, sub, &used)
        ));
    }

    // Value validation.
    let mut mime_val: Option<Mime> = None;
    let mut handler_val: Option<Handler> = None;
    let mut paths_val: Vec<UserPath> = Vec::new();
    let mut args_val: Vec<String> = Vec::new();
    let mut db_cache: Option<MimeDb> = None;
    for (i, p) in sub.pos.iter().enumerate() {
        for v in &values[i] {
            let display = pos_display(p, true);
            if v.is_empty() {
                error_exit(&format!(
                    "The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help",
                    display,
                    sub_help_usage(bin, sub)
                ));
            }
            let s = lossy(v);
            let res: Result<()> = match p.kind {
                PosKind::Mime => {
                    if db_cache.is_none() && s.starts_with('.') {
                        db_cache = Some(db());
                    }
                    parse_mime_arg(&s, db_cache.as_ref()).map(|m| mime_val = Some(m))
                }
                PosKind::Handler => Handler::resolve(&s).map(|h| handler_val = Some(h)),
                PosKind::Path => parse_user_path(&s).map(|u| paths_val.push(u)),
                PosKind::Arg => Ok(()),
            };
            if let Err(e) = res {
                error_exit(&format!(
                    "Invalid value for '{}': {}\n\nFor more information try --help",
                    display, e
                ));
            }
        }
    }
    // Extraction of string values requires valid UTF-8.
    for (i, p) in sub.pos.iter().enumerate() {
        if p.kind == PosKind::Path || p.kind == PosKind::Arg {
            for v in &values[i] {
                match v.to_str() {
                    Some(s) => {
                        if p.kind == PosKind::Arg {
                            args_val.push(s.to_string());
                        }
                    }
                    None => fake_panic(CLAP_MATCHES_PANIC, "unexpected invalid UTF-8 code point"),
                }
            }
        }
    }

    match sub.name {
        "list" => Cmd::List { all: flags_present.contains(&"all") },
        "open" => Cmd::Open { paths: paths_val },
        "set" => Cmd::Set { mime: mime_val.unwrap(), handler: handler_val.unwrap() },
        "unset" => Cmd::Unset { mime: mime_val.unwrap() },
        "launch" => Cmd::Launch { mime: mime_val.unwrap(), args: args_val },
        "get" => Cmd::Get { json: flags_present.contains(&"json"), mime: mime_val.unwrap() },
        _ => Cmd::Add { mime: mime_val.unwrap(), handler: handler_val.unwrap() },
    }
}

fn smart_usage_named(bin: &str, sub: &Sub, used: &[Used]) -> String {
    let converted: Vec<Used> = used
        .iter()
        .map(|u| match u {
            Used::Flag(n) => Used::Flag(flag_long_for(sub, n)),
            other => other.clone(),
        })
        .collect();
    smart_usage(bin, sub, &converted)
}

pub fn parse_mime_arg(s: &str, db: Option<&MimeDb>) -> Result<Mime> {
    if s.starts_with('.') {
        let names = db.map(|d| d.mime_types_from_file_name(s)).unwrap_or_default();
        if names.is_empty() || (names.len() == 1 && names[0] == "application/octet-stream") {
            return Err(Error::Ambiguous(s.to_string()));
        }
        return Mime::parse(&names[0]).map_err(|_| Error::Ambiguous(s.to_string()));
    }
    let m = Mime::parse(s).map_err(Error::BadMime)?;
    if m.subtype().is_empty() {
        return Err(Error::BadMimeType(m));
    }
    Ok(m)
}

pub fn parse_user_path(s: &str) -> Result<UserPath> {
    match Url::parse(s) {
        Some(url) if url.scheme == "file" => match url.to_file_path() {
            Some(p) => Ok(UserPath::File(p)),
            None => Err(Error::BadPath(url.path().to_string())),
        },
        Some(url) => Ok(UserPath::Url(url)),
        None => Ok(UserPath::File(PathBuf::from(s))),
    }
}
EOF"}

