fn pos_display(p: &Pos, used: bool) -> String {
    let base = if p.required || used {
        format!("<{}>", p.name)
    } else {
        format!("[{}]", p.name)
    };
    if p.multiple {
        format!("{}...", base)
    } else {
        base
    }
