    }
    s
}

fn sub_help_usage(bin: &str, sub: &Sub) -> String {
    let mut s = format!("{} {}", bin, sub.name);
    if !sub.flags.is_empty() {
        s.push_str(" [FLAGS]");
    }
    for p in sub.pos {
        s.push(' ');
        s.push_str(&pos_display(p, false));
    }
    s
}

fn sub_help(bin: &str, sub: &Sub) -> String {
    let mut s = format!("{}-{} \n{}\n\nUSAGE:\n    {}\n", bin, sub.name, sub.about, sub_help_usage(bin, sub));
    if !sub.pos.is_empty() {
        s.push_str("\nARGS:\n");
        let names: Vec<String> = sub.pos.iter().map(|p| pos_display(p, true)).collect();
        let width = names.iter().map(|n| n.len()).max().unwrap_or(0);
        for n in names {
            s.push_str(&format!("    {:<w$}    \n", n, w = width));
        }
    }
    s.push_str("\nFLAGS:\n");
    for f in sub.flags {
        let left = match f.short {
            Some(c) => format!("-{}, --{}", c, f.long),
            None => format!("    --{}", f.long),
        };
        s.push_str(&format!("    {:<17}{}\n", left, f.help));
    }
    s.push_str("    -h, --help       Prints help information\n");
    s.push_str("    -V, --version    Prints version information\n");
    s
}

fn print_and_exit(text: &str, to_stderr: bool, code: i32) -> ! {
    use std::io::Write;
    if to_stderr {
        let mut e = std::io::stderr();
        let _ = e.write_all(text.as_bytes());
        let _ = e.flush();
    } else {
        let mut o = std::io::stdout();
        let _ = o.write_all(text.as_bytes());
        let _ = o.flush();
    }
    exit(code)
}

fn error_exit(msg: &str) -> ! {
    print_and_exit(&format!("error: {}\n", msg), true, 2)
}

fn unknown_argument(arg: &str, suggestion: &str, usage: &str) -> ! {
    error_exit(&format!(
        "Found argument '{arg}' which wasn't expected, or isn't valid in this context{suggestion}\n\nIf you tried to supply `{arg}` as a PATTERN use `-- {arg}`\n\nUSAGE:\n    {usage}\n\nFor more information try --help",
        arg = arg,
        suggestion = suggestion,
        usage = usage
    ))
}

fn lossy(s: &OsStr) -> String {
