}

fn smart_usage(bin: &str, sub: &Sub, used: &[Used]) -> String {
    // Used arguments that are not required.
    let extra: Vec<&Used> = used
        .iter()
        .filter(|u| match u {
            Used::Flag(_) => true,
            Used::Pos(i) => !sub.pos[*i].required,
        })
        .collect();
    if extra.is_empty() {
        return sub_help_usage(bin, sub);
    }
    let mut s = format!("{} {}", bin, sub.name);
    for (idx, p) in sub.pos.iter().enumerate() {
        if p.required || used.contains(&Used::Pos(idx)) {
            s.push(' ');
            s.push_str(&pos_display(p, true));
        }
    }
    for u in &extra {
        if let Used::Flag(name) = u {
            s.push_str(&format!(" --{}", name));
        }
    }
    s
}

fn flag_long_for(sub: &Sub, name: &str) -> &'static str {
    match name {
        "help" => "help",
        "version" => "version",
        _ => sub.flags.iter().find(|f| f.name == name).map(|f| f.long).unwrap_or("help"),
    }
}

fn parse_sub(bin: &str, sub: &Sub, args: &[OsString], db: &dyn Fn() -> MimeDb) -> Cmd {
    let mut used: Vec<Used> = Vec::new();
    let mut flags_present: Vec<&'static str> = Vec::new();
    let mut values: Vec<Vec<OsString>> = sub.pos.iter().map(|_| Vec::new()).collect();
    let mut pos_index = 0usize;
    let mut trailing = false;

    let mut set_flag = |flag: &'static Flag, used: &mut Vec<Used>, flags_present: &mut Vec<&'static str>| {
        if flags_present.contains(&flag.name) {
            error_exit(&format!(
                "The argument '--{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help",
                flag.long,
                sub_help_usage(bin, sub)
            ));
        }
        flags_present.push(flag.name);
        used.push(Used::Flag(flag.name));
    };

    for raw in args {
        let bytes = raw.as_encoded_bytes();
        if !trailing {
            if bytes == b"--" {
                trailing = true;
                continue;
            }
            if bytes.starts_with(b"--") {
                let s = match raw.to_str() {
                    Some(s) => s,
                    None => fake_panic(CLAP_PARSER_PANIC, "unexpected invalid UTF-8 code point"),
                };
                let name = s[2..].split('=').next().unwrap_or("");
                if name == "help" {
                    print_and_exit(&sub_help(bin, sub), false, 0);
                }
                if name == "version" {
                    print_and_exit(&format!("{}-{} \n", bin, sub.name), false, 0);
                }
                if let Some(flag) = sub.flags.iter().find(|f| f.long == name) {
                    set_flag(flag, &mut used, &mut flags_present);
                    continue;
                }
                let mut longs: Vec<&str> = sub.flags.iter().map(|f| f.long).collect();
                longs.push("help");
                longs.push("version");
                let arg = format!("--{}", name);
                if let Some(c) = did_you_mean(name, &longs) {
                    let fname: &'static str = match c {
                        "help" => "help",
                        "version" => "version",
                        other => sub.flags.iter().find(|f| f.long == other).map(|f| f.name).unwrap_or("help"),
                    };
                    let mut u = used.clone();
                    if !u.contains(&Used::Flag(fname)) {
                        u.push(Used::Flag(fname));
                    }
                    let usage = smart_usage_named(bin, sub, &u);
                    unknown_argument(&arg, &format!("\n\n\tDid you mean '--{}'?", c), &usage);
                }
                let usage = smart_usage_named(bin, sub, &used);
                unknown_argument(&arg, "", &usage);
            }
            if bytes.starts_with(b"-") && bytes.len() > 1 {
                let s = lossy(raw);
                for c in s[1..].chars() {
                    if c == 'h' {
                        print_and_exit(&sub_help(bin, sub), false, 0);
                    }
                    if c == 'V' {
                        print_and_exit(&format!("{}-{} \n", bin, sub.name), false, 0);
                    }
                    if let Some(flag) = sub.flags.iter().find(|f| f.short == Some(c)) {
                        set_flag(flag, &mut used, &mut flags_present);
                        continue;
                    }
                    unknown_argument(&format!("-{}", c), "", &sub_help_usage(bin, sub));
                }
                continue;
            }
        }
        if pos_index < sub.pos.len() {
            if values[pos_index].is_empty() {
                used.push(Used::Pos(pos_index));
            }
            values[pos_index].push(raw.clone());
            if !sub.pos[pos_index].multiple {
                pos_index += 1;
            }
        } else {
            unknown_argument(&lossy(raw), "", &sub_help_usage(bin, sub));
        }
    }

    // Required arguments.
    let missing: Vec<String> = sub
        .pos
        .iter()
        .enumerate()
        .filter(|(i, p)| p.required && values[*i].is_empty())
        .map(|(_, p)| pos_display(p, true))
        .collect();
    if !missing.is_empty() {
        let list: String = missing.iter().map(|m| format!("\n    {}", m)).collect();
        error_exit(&format!(
            "The following required arguments were not provided:{}\n\nUSAGE:\n    {}\n\nFor more information try --help",
            list,
            smart_usage_named(bin, sub, &used)
        ));
    }

    // Value validation.
    let mut mime_val: Option<Mime> = None;
    let mut handler_val: Option<Handler> = None;
    let mut paths_val: Vec<UserPath> = Vec::new();
    let mut args_val: Vec<String> = Vec::new();
    let mut db_cache: Option<MimeDb> = None;
    for (i, p) in sub.pos.iter().enumerate() {
        for v in &values[i] {
            let display = pos_display(p, true);
            if v.is_empty() {
                error_exit(&format!(
                    "The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help",
                    display,
                    sub_help_usage(bin, sub)
                ));
            }
            let s = lossy(v);
            let res: Result<()> = match p.kind {
                PosKind::Mime => {
                    if db_cache.is_none() && s.starts_with('.') {
                        db_cache = Some(db());
                    }
                    parse_mime_arg(&s, db_cache.as_ref()).map(|m| mime_val = Some(m))
                }
                PosKind::Handler => Handler::resolve(&s).map(|h| handler_val = Some(h)),
                PosKind::Path => parse_user_path(&s).map(|u| paths_val.push(u)),
                PosKind::Arg => Ok(()),
            };
            if let Err(e) = res {
                error_exit(&format!(
                    "Invalid value for '{}': {}\n\nFor more information try --help",
                    display, e
                ));
            }
        }
    }
    // Extraction of string values requires valid UTF-8.
    for (i, p) in sub.pos.iter().enumerate() {
        if p.kind == PosKind::Path || p.kind == PosKind::Arg {
            for v in &values[i] {
                match v.to_str() {
                    Some(s) => {
                        if p.kind == PosKind::Arg {
                            args_val.push(s.to_string());
                        }
                    }
                    None => fake_panic(CLAP_MATCHES_PANIC, "unexpected invalid UTF-8 code point"),
                }
            }
        }
    }

    match sub.name {
        "list" => Cmd::List { all: flags_present.contains(&"all") },
        "open" => Cmd::Open { paths: paths_val },
        "set" => Cmd::Set { mime: mime_val.unwrap(), handler: handler_val.unwrap() },
        "unset" => Cmd::Unset { mime: mime_val.unwrap() },
        "launch" => Cmd::Launch { mime: mime_val.unwrap(), args: args_val },
        "get" => Cmd::Get { json: flags_present.contains(&"json"), mime: mime_val.unwrap() },
        _ => Cmd::Add { mime: mime_val.unwrap(), handler: handler_val.unwrap() },
    }
}

fn smart_usage_named(bin: &str, sub: &Sub, used: &[Used]) -> String {
    let converted: Vec<Used> = used
        .iter()
        .map(|u| match u {
            Used::Flag(n) => Used::Flag(flag_long_for(sub, n)),
            other => other.clone(),
        })
        .collect();
    smart_usage(bin, sub, &converted)
}

pub fn parse_mime_arg(s: &str, db: Option<&MimeDb>) -> Result<Mime> {
    if s.starts_with('.') {
        let names = db.map(|d| d.mime_types_from_file_name(s)).unwrap_or_default();
        if names.is_empty() || (names.len() == 1 && names[0] == "application/octet-stream") {
            return Err(Error::Ambiguous(s.to_string()));
        }
        return Mime::parse(&names[0]).map_err(|_| Error::Ambiguous(s.to_string()));
    }
    let m = Mime::parse(s).map_err(Error::BadMime)?;
    if m.subtype().is_empty() {
        return Err(Error::BadMimeType(m));
    }
    Ok(m)
}

pub fn parse_user_path(s: &str) -> Result<UserPath> {
    match Url::parse(s) {
        Some(url) if url.scheme == "file" => match url.to_file_path() {
            Some(p) => Ok(UserPath::File(p)),
            None => Err(Error::BadPath(url.path().to_string())),
        },
        Some(url) => Ok(UserPath::Url(url)),
        None => Ok(UserPath::File(PathBuf::from(s))),
    }
}
