use std::process::exit;

use apps::MimeApps;
use cli::{Cmd, UserPath};
use config::Config;
use desktop::{notify, stdout_is_tty, Ctx, Handler, Mode};
use error::{Error, Result};
use mime::Mime;
use mimedb::MimeDb;

fn mime_for_path(db: &MimeDb, path: &std::path::Path) -> Result<Mime> {
    if path.to_str().is_none() {
        return Err(Error::Ambiguous(path.to_string_lossy().into_owned()));
    }
    let guess = db.guess(path);
    if guess == "application/octet-stream" {
        return Err(Error::Ambiguous(path.to_string_lossy().into_owned()));
    }
    Mime::parse(&guess).map_err(Error::BadMime)
}

fn run(cmd: Cmd, config: &Config, apps: &mut MimeApps) -> Result<()> {
    match cmd {
        Cmd::List { all } => {
            apps.print(all);
        }
        Cmd::Set { mime, handler } => {
            apps.set_handler(mime, handler);
            apps.save()?;
        }
        Cmd::Add { mime, handler } => {
            apps.add_handler(mime, handler);
            apps.save()?;
        }
        Cmd::Unset { mime } => {
            apps.remove_handler(&mime)?;
        }
        Cmd::Get { json, mime } => {
            let handler = apps.get_handler(config, &mime)?;
            if json {
                let entry = handler.get_entry()?;
                let ctx = Ctx { config, apps };
                let (cmd, args) = entry.get_cmd(&ctx, vec![])?;
                let full = format!("{} {}", cmd, args.join(" "));
                println!(
                    "{}",
                    json::object(&[("handler", &handler.0), ("name", &entry.name), ("cmd", &full)])
                );
            } else {
                println!("{}", handler.0);
            }
        }
        Cmd::Launch { mime, args } => {
            let handler = apps.get_handler(config, &mime)?;
            let entry = handler.get_entry()?;
            let ctx = Ctx { config, apps };
            entry.exec(&ctx, Mode::Launch, args)?;
        }
        Cmd::Open { paths } => {
            let mut groups: Vec<(Handler, Vec<String>)> = Vec::new();
            let mut db: Option<MimeDb> = None;
            for path in paths {
                let (mime, arg) = match &path {
                    UserPath::Url(u) => (
                        Mime::parse(&format!("x-scheme-handler/{}", u.scheme)).map_err(Error::BadMime)?,
                        u.serialize(),
                    ),
                    UserPath::File(p) => {
                        if db.is_none() {
                            db = Some(MimeDb::load());
                        }
                        (mime_for_path(db.as_ref().unwrap(), p)?, p.to_string_lossy().into_owned())
                    }
                };
                let handler = apps.get_handler(config, &mime)?;
                match groups.iter_mut().find(|(h, _)| *h == handler) {
                    Some((_, v)) => v.push(arg),
                    None => groups.push((handler, vec![arg])),
                }
            }
            let ctx = Ctx { config, apps };
            for (handler, args) in groups {
                let entry = handler.get_entry()?;
                entry.exec(&ctx, Mode::Open, args)?;
            }
        }
    }
    Ok(())
}

fn main() {
    let config = config::load();
    let mut apps = MimeApps::load();
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let cmd = cli::parse(args, &MimeDb::load);
    match run(cmd, &config, &mut apps) {
        Ok(()) => exit(0),
        Err(e) => {
            if stdout_is_tty() {
                eprintln!("{}", e);
                exit(1);
            }
            match notify("handlr error", &e.to_string()) {
                Ok(()) => exit(1),
                Err(io) => {
                    eprintln!("Error: {:?}", Error::Io(io));
                    exit(1);
                }
            }
        }
    }
}
