#!/usr/bin/env python3
import os, sys, subprocess, shutil, tempfile, re, json

ORIG='/tmp/orig/executable'
MINE='/tmp/mine/executable'

def norm(s):
    s = re.sub(rb"thread 'main' \(\d+\)", b"thread 'main' (PID)", s)
    return s

def setup_home(base, files):
    home = os.path.join(base, 'home')
    os.makedirs(home)
    for path, content in files.items():
        full = os.path.join(home, path) if not path.startswith('/') else os.path.join(base, path.lstrip('/'))
        if content is None:
            os.makedirs(full, exist_ok=True); continue
        os.makedirs(os.path.dirname(full), exist_ok=True)
        mode = 'wb' if isinstance(content, bytes) else 'w'
        with open(full, mode) as f: f.write(content)
    return home

def snapshot(home):
    out = {}
    for root, dirs, fs in os.walk(home):
        for f in fs:
            p = os.path.join(root, f)
            rel = os.path.relpath(p, home)
            try:
                out[rel] = open(p,'rb').read()
            except Exception as e:
                out[rel] = b'<unreadable>'
    return out

def run_one(binary, case, tty=False):
    base = tempfile.mkdtemp(prefix='dt')
    home = setup_home(base, case.get('files', {}))
    env = {'HOME': home, 'PATH': case.get('path', '/usr/bin:/bin'), 'LANG': 'C.UTF-8'}
    for k, v in case.get('env', {}).items():
        env[k] = v.replace('$BASE', base).replace('$HOME', home)
    args = [a.replace('$BASE', base).replace('$HOME', home) if isinstance(a, str) else a for a in case['args']]
    cwd = case.get('cwd', '/workspace').replace('$BASE', base).replace('$HOME', home)
    if tty:
        cmd = 'exec ' + ' '.join("'" + a.replace("'", "'\\''") + "'" for a in [binary] + args)
        p = subprocess.run(['script', '-qec', cmd, '/dev/null'], capture_output=True, env=env, cwd=cwd, stdin=subprocess.DEVNULL, timeout=20)
    else:
        p = subprocess.run([binary] + args, capture_output=True, env=env, cwd=cwd, stdin=subprocess.DEVNULL, timeout=20)
    if case.get('sleep'):
        import time; time.sleep(case['sleep'])
    snap = snapshot(home)
    extra = b''
    if case.get('log'):
        lp = case['log'].replace('$BASE', base)
        try: extra = open(lp,'rb').read()
        except: extra = b'<nolog>'
    shutil.rmtree(base, ignore_errors=True)
    def fix(b): return norm(b.replace(base.encode(), b'$BASE'))
    return (p.returncode, fix(p.stdout), fix(p.stderr), {k: fix(v) for k, v in snap.items()}, fix(extra))

def compare(case, tty=False):
    a = run_one(ORIG, case, tty)
    b = run_one(MINE, case, tty)
    ok = a == b
    return ok, a, b

def show(name, a, b):
    labels = ['rc', 'stdout', 'stderr', 'files', 'log']
    for i, l in enumerate(labels):
        if a[i] != b[i]:
            print(f'  [{name}] {l} differs:')
            if l == 'files':
                ks = set(a[i]) | set(b[i])
                for k in sorted(ks):
                    if a[i].get(k) != b[i].get(k):
                        print(f'    file {k}:\n      orig={a[i].get(k)!r}\n      mine={b[i].get(k)!r}')
            else:
                print(f'    orig={a[i]!r}\n    mine={b[i]!r}')

if __name__ == '__main__':
    cases_file = sys.argv[1]
    ns = {}
    exec(open(cases_file).read(), ns)
    cases = ns['CASES']
    fails = 0
    only = sys.argv[2] if len(sys.argv) > 2 else None
    for i, case in enumerate(cases):
        name = case.get('name', ' '.join(map(str, case['args'])))
        if only and only not in name: continue
        for tty in ([False, True] if case.get('tty') == 'both' else [case.get('tty', False)]):
            ok, a, b = compare(case, tty)
            if not ok:
                fails += 1
                print(f'FAIL {i}: {name} (tty={tty})')
                show(name, a, b)
    print(f'{len(cases)} cases, {fails} failures')
EOF
