        return V4::NotIpv4;
    }
    let mut parts: Vec<&str> = input.split('.').collect();
    if parts.last() == Some(&"") {
        parts.pop();
    }
    if parts.len() > 4 {
        return V4::NotIpv4;
    }
    let mut numbers: Vec<u64> = Vec::new();
    for part in &parts {
        if part.is_empty() {
            return V4::NotIpv4;
        }
        match parse_ipv4_number(part) {
            Some(n) => numbers.push(n),
            None => return V4::NotIpv4,
        }
    }
    let last = match numbers.pop() {
        Some(l) => l,
        None => return V4::NotIpv4,
    };
    if last > (u32::MAX as u64) >> (8 * numbers.len() as u32) {
        return V4::Invalid;
    }
    if numbers.iter().any(|n| *n > 255) {
        return V4::Invalid;
    }
    let mut ipv4 = last;
    for (i, n) in numbers.iter().enumerate() {
        ipv4 += n << (8 * (3 - i as u64));
    }
    V4::Addr(format!(
        "{}.{}.{}.{}",
        (ipv4 >> 24) & 255,
        (ipv4 >> 16) & 255,
        (ipv4 >> 8) & 255,
        ipv4 & 255
    ))
}

